/* 第二十七章 · 姜维诈降 — 逆向自 R_27.EEX */
(function(){
 if(!window.JW_CHAPTERS) window.JW_CHAPTERS=[];
 window.JW_CHAPTERS.push({"id":"ch27","num":27,"title":"第二十七章 · 姜维诈降","desc":"第二十七章 · 姜维诈降（原版剧本 R_27.EEX）","map":"assets/maps/map27.png","intro":{"title":"第二十七章 · 姜维诈降","nodes":[{"type":"scene","bg":"default","name":"杨戏暴言"},{"type":"scene","bg":"default","name":"姜维军营帐"},{"type":"say","who":"杨戏","text":"哈哈哈哈哈，我们天下无敌的姜维大将军居然开始把责任都推给邓艾了。"},{"type":"say","who":"杨戏","text":"当年先帝带领的大汉军队面对曹操毫无惧色，丞相所带领的大汉军队更是压倒司马懿。"},{"type":"say","who":"杨戏","text":"而如今在我们姜维大将军带领下的大汉军队，居然碰到邓艾这二流角色就束手无策。"},{"type":"say","who":"杨兰","text":"邓艾哪里是二流角色？"},{"type":"say","who":"杨戏","text":"邓艾是贼营的首领？邓艾是贼营的最高军事统帅？不，他什么都不是，只不过是个地方小都督而已，你却打不赢他。"},{"type":"say","who":"杨戏","text":"想我大汉的子弟兵还真可怜，居然被这样无能的将领给统率著。"},{"type":"say","who":"柳隐","text":"这是什么话？武将的能力可以用官阶来衡量？"},{"type":"say","who":"句扶","text":"这个邓艾的用兵能力，你刚才也亲眼看见，为什么还能说这种不负责任的话？"},{"type":"say","who":"姜维","text":"两位，别再争辩了，这次确实是我的失职，他说的一点也没错。"},{"type":"say","who":"姜维","text":"不过，现在应该是该想如何安全撤退的时候，其他的事情等回到成都再说。"},{"type":"say","who":"姜维","text":"（我这辈子从来没有那么窝囊过，面对杨戏的嘲讽，居然连一点反击的能力都没有。）"},{"type":"say","who":"向充","text":"（我不认为被这样说后，会一点都不在意，应该是刻意压制不发作吧。）"},{"type":"say","who":"来忠","text":"（想想这个人是谯周推荐来的，难道他的目的就是想让这人羞辱大将军而已？）"},{"type":"say","who":"宁随","text":"（伯约，你得继续忍下去。不然，你会变得比现在更孤立。）杨戏失势成都皇宫"},{"type":"say","who":"杨戏","text":"陛下，这次追随后将军姜维出征的结果，在此向您报告。"},{"type":"say","who":"杨戏","text":"后将军姜维，与贼将邓艾相持半年后，无计可施，最后率军撤退。"},{"type":"say","who":"杨戏","text":"他多年来劳师动众，最终却没有获得任何成果，平白耗损大量人力物力，害得现在大汉民不聊生，怨声载道。"},{"type":"say","who":"刘禅","text":"果然是这样吗？"},{"type":"say","who":"文官","text":"启禀陛下，微臣刚才调查完关于杨戏的案件，现在正式向您提出弹劾案。"},{"type":"say","who":"杨戏","text":"弹劾？这是怎么回事？"},{"type":"say","who":"谯周","text":"你是不是搞错了什么？文然可是和张表等人齐名的名士。"},{"type":"say","who":"谯周","text":"（过去很多人认为我无当世才，只有文然他敬重我，我怎么可以眼睁睁看著他受到陷害！）"},{"type":"say","who":"文官","text":"没有错，他在担任建宁太守任内收受南中大姓的贿赂，好让他们取得当地管理特权。"},{"type":"say","who":"杨戏","text":"这真是胡说八道，我从来就没有收过南中大姓一毛钱！"},{"type":"say","who":"文官","text":"我有的是人证和物证，你再怎么狡辩也没有用。"},{"type":"say","who":"刘禅","text":"想不到声誉卓著的射声校尉居然会作出这样的事情…"},{"type":"say","who":"杨戏","text":"陛下，冤枉啊！"},{"type":"say","who":"谯周","text":"臣愿意担保文然的清白，请陛下明察！"},{"type":"say","who":"刘禅","text":"在事情弄清楚以前，就请射声校尉你先行停职。"},{"type":"say","who":"杨戏","text":"陛下，我真的什么都没有…等一下，我明白了，是姜维，是姜维那个家伙陷害我！"},{"type":"say","who":"刘禅","text":"后将军有什么理由要陷害你？"},{"type":"say","who":"杨戏","text":"他因为在秦川被邓艾打得七零八落，而臣在当时批评了他的用兵，姜维因此怀恨在心，指派底下的人陷害我。"},{"type":"say","who":"刘禅","text":"你有证据？"},{"type":"say","who":"杨戏","text":"这……"},{"type":"say","who":"刘禅","text":"没有证据，就这样污蔑大汉的栋梁，这样的行为可以吗？"},{"type":"say","who":"刘禅","text":"过去相父曾经说过：“来敏乱群，过于孔文举。”难道你也要效法来敏？"},{"type":"say","who":"刘禅","text":"不用调查了，朕直接贬你为庶人，希望你能反省你自己犯下的过错。"},{"type":"say","who":"杨戏","text":"呜呜呜…我大汉现在是奸臣当道啊，姜维你这个奸臣，我真恨不能将你赶出大汉。"},{"type":"say","who":"杨戏","text":"想我撰写《季汉辅臣赞》，颂赞大汉开国时的英雄元勋，和这些人相比，现在大汉真的是没有人才呀！"},{"type":"say","who":"谯周","text":"（姜维，你这次实在是太过分了，本来我只有对你连年用兵有意见，现在我连你这个人都彻底鄙视了。）"},{"type":"say","who":"诸葛瞻","text":"（姜维这个可恶的家伙，姊姊音信全无，却没有一点愧疚的表示，现在居然还忙著对政敌清算斗争。）"},{"type":"say","who":"郤正","text":"（这怎么看都不像是伯约的作为，莫非是陈祗？）"},{"type":"say","who":"陈祗","text":"…………忠心成都皇宫"},{"type":"say","who":"陈祗","text":"陛下，虽然这样的行动会造成姜维的名声受损，但绝对不能就这样放任益州人在那大放厥词。"},{"type":"say","who":"刘禅","text":"还是尚书令你懂朕的心，要是朝中大臣都像你一样就好了。"},{"type":"say","who":"陈祗","text":"诸葛瞻等人的意见固然正确，姜维这几年的出兵并没有带来正面的结果。"},{"type":"say","who":"陈祗","text":"然而他们却忽略一件事，就是大汉上下能够有这才能领兵对抗曹贼的，也只有姜维而已。"},{"type":"say","who":"黄皓","text":"可是我不懂，为什么姜维这一介武夫会如此受到陛下看重？"},{"type":"say","who":"陈祗","text":"对陛下来说，姜维可是比丞相更可靠，因为他几乎不属于任何集团，这样的人自然只会效忠陛下。"},{"type":"say","who":"陈祗","text":"不如请陛下利用这个机会，反正姜维这次出兵虽没有大胜，但也没败，就顺水推舟再封他为大将军吧。"},{"type":"say","who":"刘禅","text":"嗯，真是好主意。爱卿呀，朕要是没有你，朕真的不知道该怎么办呀。"},{"type":"say","who":"陈祗","text":"陛下，您真的太过奖了，臣没有这样的本事，只是一心想为陛下服务而已。"},{"type":"say","who":"陈祗","text":"咳咳…咳咳咳…"},{"type":"say","who":"刘禅","text":"尚书令，你不要紧吧，看你最近精神似乎很不好的样子。"},{"type":"say","who":"陈祗","text":"臣没事，让陛下担心了。"},{"type":"say","who":"黄皓","text":"（为了让姜维复职，陈祗几乎一个人顶住所有的反对声浪，难怪搞垮自己身体。）"},{"type":"say","who":"黄皓","text":"（我真的不懂，为什么连陈祗这样的人，都会愿意为姜维做到这种地步？）三日后，姜维再度被封为大将军。然而因为这场战争，姜维没有任何建树，所以这样的人事任命，也有不小的反对声浪。人性的弱点姜维军营帐"},{"type":"say","who":"宁随","text":"虽然向充不太高兴，不过接下来我希望来忠你也能参加我们的讨论。"},{"type":"say","who":"向充","text":"若不是因为你肯认错，还说服你父亲不再扯我们后腿，我抵死都不会让你进来。"},{"type":"say","who":"来忠","text":"如果有什么需要在下效劳的地方，请尽管吩咐。"},{"type":"say","who":"宁随","text":"其实也没什么特别的事情，只是要你们知道，伯约也是性情中人，也会做出符合人性的事情。"},{"type":"say","who":"来忠","text":"难道是杨戏的事情？我认为那背后一定有别人在操纵，最有可能就是尚书令陈祗。"},{"type":"say","who":"向充","text":"没错，益州人大老谯周和杨戏关系密切，一旦杨戏受难，他一定会憎恨大将军。"},{"type":"say","who":"宁随","text":"你们两个说的完全正确，我也认为那是陈祗做的好事。"},{"type":"say","who":"宁随","text":"只是你们忽略了一件事，伯约他大可以阻止这样的事情发生，然而他却默不吭声，默许杨戏被罢免。"},{"type":"say","who":"来忠","text":"大将军为人坦荡，从来不用暗箭伤人的手段，更不会与人结怨，我认为您实在"},{"type":"say","who":"旁白","text":"▶ 是太多虑了。"},{"type":"say","who":"宁随","text":"确实如此。三十年前，伯约不但原谅我对他的陷害，反而诚恳地求我加入常败军。"},{"type":"say","who":"宁随","text":"我折服的不是他的才能，而是他宽阔的胸襟。"},{"type":"say","who":"宁随","text":"然而现在情况却不同，和邓艾交手的连续挫败，已经让他的自尊心受到严重打击了吧。"},{"type":"say","who":"来忠","text":"邓艾虽然两次让大将军受挫，但是不可能会给大将军那么大的打击呀。"},{"type":"say","who":"向充","text":"明明大将军以前面对过像是郭淮或是陈泰那样的对手，也不是没有受挫过，怎么可能碰到邓艾就会变了样？"},{"type":"say","who":"宁随","text":"你们很容易陷入贵古贱今的思维中，但以我看过这么多名将的经历，能和邓艾这个怪物相比的，可能是张郃或是司马懿。"},{"type":"say","who":"宁随","text":"然而如果单纯就用兵的手腕来看，能和他比的，可能只有曹操了。"},{"type":"say","who":"来忠","text":"他有这么厉害？"},{"type":"say","who":"宁随","text":"短时间之内把一个残破的军区整顿成军事重镇，残兵败将变成精锐，这都不是寻常人可以做到的。"},{"type":"say","who":"宁随","text":"他的存在完全颠覆了伯约的思考，也让伯约的信心受到打击。"},{"type":"say","who":"向充","text":"我明白了，所以我们应该要在后面支撑住大将军，不要让他因为失意而做出更多会后悔的事情。"},{"type":"say","who":"来忠","text":"我认为虽然被陈祗摆了一道，不过他的用意应该只是要让我们变得更依赖他。"},{"type":"say","who":"来忠","text":"以陈祗受到皇上重视的情况来看，我认为依附他没有坏处。"},{"type":"say","who":"宁随","text":"确实有他在，圣上绝对会挺我们，但只怕陈祗不在的一天…担心的对象姜维军营帐"},{"type":"say","who":"杨兰","text":"我可以体会你的心情，但是你有想过，对杨戏下手，只会害你变得更孤立？"},{"type":"say","who":"姜维","text":"我并没有对他下手…"},{"type":"say","who":"杨兰","text":"那么你明知道杨戏被弹劾这件事情绝对不单纯，为什么你还不出面阻止？"},{"type":"say","who":"姜维","text":"因为我看见陈祗孤军奋战的样子……"},{"type":"say","who":"杨兰","text":"啊？！"},{"type":"say","who":"姜维","text":"陈祗为了帮我排除障碍，不惜得罪身边所有的人，而且累到身体状况大不如前。"},{"type":"say","who":"杨兰","text":"不可能吧，那个自私自利的小人？"},{"type":"say","who":"姜维","text":"他有自私的一面，却也有重情义的一面。对一个人的评价岂能只看他一个面向？"},{"type":"say","who":"姜维","text":"至少在这个时候，我不想阻止他的作为，再继续给他造成负担了。"},{"type":"say","who":"杨兰","text":"可是外人可会认为是杨戏说的话，已经超过你可以忍耐的范围。认为是因为对邓艾连战连败，让你失去风度了。"},{"type":"say","who":"姜维","text":"你怎么知道我不是这样想的呢？我不是圣人，一样会生气，一样会怨恨…你以为我真的不在意杨戏的话？"},{"type":"say","who":"杨兰","text":"算了，我也一样讨厌杨戏，就当作是出口恶气也没什么不好。"},{"type":"say","who":"杨兰","text":"倒是，诸葛果现在在哪里呢？"},{"type":"say","who":"姜维","text":"我真的很担心她的安危，一声不响地带著赵家兄弟跑到寿春。"},{"type":"say","who":"姜维","text":"现在诸葛诞兵败身亡，如果她有万一，我该怎么向丞相交代？"},{"type":"say","who":"杨兰","text":"哦？我在乐嘉那边遭到危难，你都没有任何表示，现在居然担心诸葛果？"},{"type":"say","who":"姜维","text":"我没有这个意思…"},{"type":"say","who":"杨兰","text":"放心吧，那个女人比我聪明一百倍，我都可以从乐嘉逃出来，她会不行吗？"},{"type":"say","who":"杨兰","text":"搞不好她还有本事和曹家的人见到面呢，哈哈哈，我乱说的…"},{"type":"say","who":"姜维","text":"我想应该不可能吧…伐吴大计寿春魏军营帐"},{"type":"say","who":"司马昭","text":"我刚才思考了一下，既然唐将军和全将军等人都已经投降我大魏。"},{"type":"say","who":"司马昭","text":"我想派出轻装骑兵深入东吴，招降并且迎接唐咨等人的子弟。如果有机可乘，就发动攻击，消灭东吴。"},{"type":"say","who":"王基","text":"大将军，此举万万不可。"},{"type":"say","who":"王基","text":"过去诸葛恪趁著东关战胜余威，集结江东所有兵力，包围合肥新城，既不能攻克，兵士死亡超过一半。"},{"type":"say","who":"王基","text":"姜维趁著洮西大胜余威，用轻装部队深入我们国土，终因粮草不能供应，在上邽全军覆没。"},{"type":"say","who":"王基","text":"大胜之后，上下都会产生一种轻敌的心理，不能平心静气地作周密的考虑。"},{"type":"say","who":"王基","text":"今贼军在外受到挫败，内部争执没有平息，正是他们加强战备，因应变化之际。"},{"type":"say","who":"王基","text":"而我们大军出动已超过一年，每个人都有思乡之念，但愿早回故乡。"},{"type":"say","who":"王基","text":"俘虏十万，叛徒伏法，能如此获得重大胜利而没受损失，自古以来也寥寥可数。"},{"type":"say","who":"王基","text":"武皇帝在官渡击败袁绍，认为获得已经够多，不再追击，就是害怕受到挫折，使得来不易的威严丧失。"},{"type":"say","who":"司马昭","text":"你说的有道理，我这就下令撤兵。"},{"type":"say","who":"司马昭","text":"扬州这边就交给你了，我会奏请圣上封你为征东将军，都督扬州诸军事。"},{"type":"say","who":"王基","text":"多谢大将军！"},{"type":"say","who":"王基","text":"（就当作自己是为大魏效命，至少司马昭还是大魏的大将军…对吧…呵呵呵，我王基什么时候变得这么可悲了…）"},{"type":"say","who":"鲁芝","text":"（王基呀，你再继续骗自己也减轻不了内心的痛苦，我们两个都是一样可悲的人。）"},{"type":"say","who":"司马昭","text":"（若不是王伯舆的提醒，我还真差点忘记东关之战的惨痛教训。）"},{"type":"say","who":"司马昭","text":"（东吴军队在保家卫土上能够发挥的战斗力非常惊人，绝对不是我现在看到的这种水准。）"},{"type":"say","who":"司马昭","text":"（我就先整顿内部吧，想想曹髦那个小子，他才是我当前最需要对付的人。）王基的看法马上就应验了，孙綝率军回国后，因为自己没有战功，加上皇帝孙亮又不断责问他，孙綝索性躲在巢湖不归。孙亮对于孙綝的行为感到气愤无比，决定要对这个跋扈的权臣发动攻势，双方的冲突一触即发。大虎的抉择建业皇宫"},{"type":"say","who":"孙亮","text":"鲁班公主，你知道自己做了什么事？"},{"type":"say","who":"孙鲁班","text":"圣上，您说这话是什么意思，我不懂。"},{"type":"say","who":"孙亮","text":"你骗了朕，害朕冤杀了朱损和朱熊兄弟，你可知罪？"},{"type":"say","who":"孙鲁班","text":"圣上没有冤杀他们，我那两个外甥怨恨自己的庶母，所以才会陷害妹妹，诬告她要杀害孙峻。"},{"type":"say","who":"孙亮","text":"你不要再撒谎了，朕已经知道是你向孙峻进谗言，害死小虎姊姊的。"},{"type":"say","who":"孙鲁班","text":"孙峻都已经死了，我说什么都没办法辩解。"},{"type":"say","who":"孙亮","text":"你知道小虎姊姊对朕有多重要？"},{"type":"say","who":"孙亮","text":"朕的母亲只知道争权夺利，对朕没有给过一点点的母爱。"},{"type":"say","who":"孙亮","text":"只有小虎姊姊愿意陪我，在朕最孤独的时候给朕温暖。她是比朕亲娘还要亲的，你不知道吗？"},{"type":"say","who":"孙鲁班","text":"圣上，我知道错了，给我个机会吧！"},{"type":"say","who":"孙亮","text":"反正朕杀害朱损的事情，每个人都知道是你陷害他的。"},{"type":"say","who":"孙亮","text":"你为了让自己逃过一劫，却让自己陷入更大的危险。"},{"type":"say","who":"孙亮","text":"你该不会不知道，朱损的妻子就是孙峻的妹妹吧。"},{"type":"say","who":"孙鲁班","text":"这个…"},{"type":"say","who":"孙亮","text":"你动到了他的亲戚，请问孙綝会怎么想？"},{"type":"say","who":"孙亮","text":"现在你全家班经过上次孙綝的整肃，剩下也没有多少了，你们钱塘全家的地位迟早会被取代。"},{"type":"say","who":"孙亮","text":"而孙綝本人也对你不理不采，你根本就无法用对付孙峻的那招来色诱孙綝。"},{"type":"say","who":"孙鲁班","text":"圣上，您是要我跟您联手对付孙綝是吗？"},{"type":"say","who":"孙亮","text":"完全正确，朕会给你们全家班能够对抗孙綝的地位，只要事情成功，你们就是我大吴的栋梁。"},{"type":"say","who":"孙鲁班","text":"（我这个蠢弟弟，以为他懂得看老鼠屎就可以对付孙綝。）"},{"type":"say","who":"孙鲁班","text":"（一个连滕胤和吕据两位先帝顾命大臣联手都扳不倒的政争高手，岂是你一个小毛头对付得了的？）"},{"type":"say","who":"孙鲁班","text":"（现在的我也没有选择了，不和他联手，我会当场死在这里。和他联手，大概不久后也会死在孙綝手上吧。）"},{"type":"say","who":"孙鲁班","text":"（呵呵呵，我玩弄阴谋多时，到最后却被自己的阴谋困死。妹妹，你现在应该在那边笑我笑得很愉快吧。）孙亮联合鲁班公主、将军刘丞和卫将军全尚等人，密谋诛杀孙綝。孙亮特别嘱咐全尚的儿子全纪，不准将计画透露给自己娘亲知道，因为她是孙綝的堂姊，很容易透露口风。然而全纪却把这计画告诉自己父亲全尚，而全尚又让自己妻子知道这计画，终于整个密谋曝了光。孙綝反击巢湖基地"},{"type":"say","who":"孙綝","text":"你把圣上说的话，原原本本告诉我。"},{"type":"say","who":"武官","text":"您真的想听？"},{"type":"say","who":"孙綝","text":"对！"},{"type":"say","who":"武官","text":"圣上说您专权弄势，根本没有把他放在眼里。"},{"type":"say","who":"武官","text":"寿春之战时，圣上下令要您火速上岸前进，您却留在船上，不肯登陆一步。"},{"type":"say","who":"武官","text":"您又把罪状推到朱异头上，事先没有报告便诛杀功臣。又在朱雀桥南，兴筑高宅大院，不再朝见，自由自在，毫无顾忌。"},{"type":"say","who":"孙綝","text":"那么圣上的计画是什么？"},{"type":"say","who":"武官","text":"圣上要卫将军全尚秘密集结兵马，他还准备亲自到朱雀桥，率领左右无难军包围您的住宅。"},{"type":"say","who":"孙綝","text":"孙亮啊，这可是你逼我的，本来我还不想这样做的。"},{"type":"say","who":"武官","text":"大将军，莫非您要…"},{"type":"say","who":"孙綝","text":"以前我最瞧不起的人，就是贼营那个叫做司马师的人。"},{"type":"say","who":"孙綝","text":"我一直认为，不管皇上有多大的过错，做臣子的只能劝谏，而不能直接废黜皇上。"},{"type":"say","who":"孙綝","text":"然而我现在才明白，司马师如果当时不那样做，恐怕只会落得满门抄斩的下场吧。"},{"type":"say","who":"孙綝","text":"传令下去，全军袭击全尚和刘丞住处，接著包围皇宫。孙綝以惊人的速度发动政变，在夜色掩护下，顺利生擒全尚，并且在苍龙门外斩杀刘丞。等到拂晓时刻，孙綝大军已经团团包围皇宫。废黜孙亮建业皇宫"},{"type":"say","who":"孙亮","text":"放开我！朕在位五年，谁敢不听从命令！"},{"type":"say","who":"孙亮","text":"朕要和那逆贼孙綝拚了！"},{"type":"say","who":"文官","text":"皇上，不要出去呀！"},{"type":"say","who":"老妇","text":"身为您的乳母，绝对不能眼睁睁看您去送死呀。"},{"type":"say","who":"孙鲁班","text":"皇上，认清楚现实吧，您已经是一败涂地了。"},{"type":"say","who":"孙亮","text":"叫全纪给我过来！都是我误信这个蠢蛋才会搞到现在这样。"},{"type":"say","who":"孙鲁班","text":"您杀了全纪又有什么用？结果根本就不会改变。"},{"type":"say","who":"孙鲁班","text":"乖乖投降吧，至少还可以像曹芳那样，苟延残喘活下去。"},{"type":"say","who":"孙亮","text":"孙綝！朕要宰了你！"},{"type":"say","who":"孙綝","text":"闭嘴！少在这边对我大呼小叫！你以为你还是皇帝？"},{"type":"say","who":"孙亮","text":"什么？！"},{"type":"say","who":"孙綝","text":"皇帝孙亮年纪轻轻就精神错乱，已经不堪任君王的地位，侍奉皇家宗庙。"},{"type":"say","who":"孙綝","text":"我已经禀告先帝在天之灵，罢黜皇帝，贬为会稽王。"},{"type":"say","who":"孙亮","text":"朕…被废了？"},{"type":"say","who":"孙綝","text":"你最好赶快回到你的封地去，不然我心情就会不好。"},{"type":"say","who":"孙綝","text":"我心情若不好，我就会不爽，我不爽我就想要报仇，我若报仇下去，下一个要死什么人，连我自己都不知道。"},{"type":"say","who":"孙綝","text":"至于你，孙大虎！我要把你流放到豫章那边。"},{"type":"say","who":"孙鲁班","text":"难道您不再考虑一下，我也可以像帮忙孙峻一样帮您…"},{"type":"say","who":"孙綝","text":"滚！你当我胃口那么好？族兄喜欢你的牛肉面，我可不喜欢！"},{"type":"say","who":"孙鲁班","text":"呜呜呜呜呜…公元二五八年，东吴大将军孙綝废黜皇帝孙亮，贬为会稽王。全尚在流放到零陵途中被杀，孙鲁班则被流放到豫章。孙綝将孙亮的罪状诏告全国，尚书桓彝不肯签名，当场遇害。其他大臣震惊恐怖，敢怒不敢言。在典军施正的建议下，孙綝决定迎立琅邪王孙休继位。孙休起意建业皇宫"},{"type":"say","who":"孙綝","text":"草莽贱臣孙綝，缴还印信和符节，请求准许辞职，避开贤才上进之路。"},{"type":"say","who":"孙休","text":"大将军别这样说，朕还有很多地方要仰仗您的。"},{"type":"say","who":"张布","text":"（孙綝这样做，摆明是要圣上给他更高的官位。一上任就面临孙綝的要胁，圣上真"},{"type":"say","who":"旁白","text":"▶ 是可怜。）"},{"type":"say","who":"虞汜","text":"（我能阻止孙綝大摇大摆住进皇宫，却不能阻止他其他嚣张跋扈的行为。唉…）"},{"type":"say","who":"孙休","text":"朕决定封大将军孙綝为丞相、荆州刺史、增加其永宁侯采邑五个县。"},{"type":"say","who":"孙休","text":"而其弟孙恩任命为御史大夫、卫将军和中军督，封县侯。"},{"type":"say","who":"孙休","text":"（孙綝，现在你要什么，朕都给你。但是这些东西，朕迟早会向你要回来。）柴桑议事厅陆抗的考量"},{"type":"say","who":"陆抗","text":"公绪你为什么会来到这个地方？"},{"type":"say","who":"施绩","text":"我想要和你共商大事。"},{"type":"say","who":"陆抗","text":"大事情？"},{"type":"say","who":"甘宁","text":"呵呵，你们两个还挺登对的。"},{"type":"say","who":"甘宁","text":"糟了，我脑中的妄想开始爆发了…果然还是弱气的施绩比较适合受。"},{"type":"say","who":"施绩","text":"拜托你不要乱讲话，人家幼节可是连儿子都已经有了。"},{"type":"say","who":"陆抗","text":"说到这个，我听说过有些对你不利的传闻，你不想澄清一下？"},{"type":"say","who":"施绩","text":"传闻？"},{"type":"say","who":"陆抗","text":"听说你和蜀国私下有来往，因为你的话，让蜀将阎宇在白帝城增兵五千。"},{"type":"say","who":"施绩","text":"不错，因为我害怕曹贼在这个时候偷袭我们。"},{"type":"say","who":"施绩","text":"但是原因你也该明白，都是孙綝这个人把我大吴弄得乌烟瘴气，才会让我必须要低声下气去求援。"},{"type":"say","who":"陆抗","text":"果然是因为孙綝…"},{"type":"say","who":"施绩","text":"幼节，不要想逃避了。人家贼营的皇帝被废黜，还有毌丘俭愿意起兵反抗。但我们呢？眼睁睁看著圣上被废却没任何动作。"},{"type":"say","who":"陆抗","text":"……"},{"type":"say","who":"施绩","text":"难道是因为孙綝刚好处理掉你最痛恨的全家人，所以你才默许他的暴行？难道你没有看到朱异的下场？"},{"type":"say","who":"施绩","text":"幼节！你还在怀疑我的立场？你看看我的姓氏就知道，我已经改姓施了，难道你还不明白？"},{"type":"say","who":"施绩","text":"我爹的养父确实和北方人关系较密切，但是当我爹想要改姓施的那刻，你就该明白他的情感还是在江东。"},{"type":"say","who":"陆抗","text":"公绪，你太小看我了。我会按兵不动是因为我必须要等到孙綝做出重大叛逆的事情，才能有像你这样的人愿意反抗。"},{"type":"say","who":"陆抗","text":"既然你都愿意出面了，我又怎么可能不加入？"},{"type":"say","who":"施绩","text":"很好，那么我会和左将军丁奉联系，说幼节你也愿意加入。"},{"type":"say","who":"甘宁","text":"呵呵呵，这么多男人凑在一起还要联络来联络去，真是娘炮…"},{"type":"say","who":"施绩","text":"这个甘家后人，你可以认真点讨论吗？"},{"type":"say","who":"甘宁","text":"如果认真就可以解决问题的话，这世上就不会有那么多人痛苦了。"},{"type":"say","who":"陆抗","text":"公绪，小甘宁说得没有错，当时滕胤或是圣上失败，都是因为联络经过太多手了。"},{"type":"say","who":"陆抗","text":"我和丁将军共事过，他应该会知道该怎么做，不需要再和他做过多的联系。"},{"type":"say","who":"施绩","text":"好，拨乱反正，就在此一举。预测永安城议事厅"},{"type":"say","who":"宗预","text":"既然看到文平到来，我也可以安心回成都去了。"},{"type":"say","who":"阎宇","text":"镇军大将军，您实在太看得起我了，我这次前来除了接替您永安督的职位外，还和施绩的那封信有关。"},{"type":"say","who":"宗预","text":"陛下似乎很重视东吴那边的局势，不过我认为东吴还没有脆弱到这么轻易被攻下。"},{"type":"say","who":"宗预","text":"更何况司马师当年东兴大败的记忆还犹存，司马昭不会轻举妄动的。"},{"type":"say","who":"阎宇","text":"那么施绩是杞人忧天？"},{"type":"say","who":"宗预","text":"或许是，但是孙綝专政造成东吴内部不和谐也是事实。"},{"type":"say","who":"罗宪","text":"难道您不担心孙綝继续乱搞下去，东吴的实力会被削弱？上次出兵寿春，结果让东吴损失了数万名军队也是事实呀。"},{"type":"say","who":"宗预","text":"孙綝他过去虽然过了好几关，但是这次他恐怕过不了这关的。"},{"type":"say","who":"罗宪","text":"怎么说？"},{"type":"say","who":"宗预","text":"这表示孙綝的作为已经让江东大族开始不满，迟早他们也会参加推倒孙綝之事。"},{"type":"say","who":"宗预","text":"若是新任皇帝孙休也决定采取行动的话，孙綝一定倒台。"},{"type":"say","who":"罗宪","text":"原来如此，不愧是对东吴局势最了解的镇军大将军。"},{"type":"say","who":"宗预","text":"比起来这个，我认为东吴之后的动向才要注意，别忘记之前他们在丞相过世后做的事情。"},{"type":"say","who":"阎宇","text":"真的会吗？我们两国的邦交不是很稳固？"},{"type":"say","who":"罗宪","text":"不，确实有可能，东吴趁机偷袭我大汉也不是第一次，过去荆州就是这样丢掉的。"},{"type":"say","who":"宗预","text":"嗯…请两位一定要记住这点，东吴虽是我们最好的盟友，却也可能是最难缠的对手，不要掉以轻心。"},{"type":"say","who":"阎宇","text":"（话虽如此，我总认为我国的情势可不会比东吴好到哪去，姜维成天胡乱出兵，搞得民不聊生，这才是最大的问题。）"},{"type":"say","who":"阎宇","text":"（希望思远或是龚袭能够早点上台，这样我才有机会取代姜维，阻止局势继续恶化下去。）政变计画建业皇宫"},{"type":"say","who":"张布","text":"之前孙綝到我家宴会的时候，他对我抱怨说如果不是因为他，圣上您怎么可能当到皇帝。"},{"type":"say","who":"孙休","text":"这个孙綝实在太嚣张跋扈了，他逼朕一步，朕就得退一步，现在已经快要无路可退了。"},{"type":"say","who":"孙休","text":"上次有人向朕告密说孙綝造反，孙綝逼迫朕交出告密的人，当场诛杀给朕看，他有把朕放在眼里？"},{"type":"say","who":"孙休","text":"现在他又想要都督武昌，朕看他是要造反了。"},{"type":"say","who":"张布","text":"陛下，其实这也表示孙綝在害怕，只要有一点风吹草动，就足够让他恐惧。"},{"type":"say","who":"张布","text":"看看他诛杀了多少人，从滕胤、吕据开始，到王惇、孙宪甚至是朱异和全尚等，从北方人到南方人，无一不有。"},{"type":"say","who":"张布","text":"现在他在朝中已经是没有朋友，身边全部都是敌人了。"},{"type":"say","who":"孙休","text":"这么说，现在是可以下手的时机？"},{"type":"say","who":"张布","text":"没错，而且微臣找来一个可以共商大事的人来帮忙。"},{"type":"say","who":"旁白","text":"▶ 是谁？"},{"type":"say","who":"张布","text":"左将军丁奉，虽然不识字，但智谋超过常人，可以担当大事。"},{"type":"say","who":"丁奉","text":"臣丁奉，拜见陛下。"},{"type":"say","who":"孙休","text":"好，朕想要把这个大事托付给你，你有这个信心？"},{"type":"say","who":"丁奉","text":"孙綝兄弟党羽成群，若是贸然发动攻击，只怕人心有变，不容易控制。"},{"type":"say","who":"丁奉","text":"最好是等到“腊八大祭”，以陛下亲兵及时擒获他，必可杀他措手不及。"},{"type":"say","who":"孙休","text":"好计画，朕就将这一切托付给你了。"},{"type":"say","who":"丁奉","text":"要扳倒孙綝并不容易，这次可能还需要借助江东大族的力量。"},{"type":"say","who":"孙休","text":"江东大族？"},{"type":"say","who":"丁奉","text":"吴郡朱家和钱塘全家的遭殃，让其他江东大族也感受到压力，因此他们的态度不会像以往那样冷漠，会愿意帮助陛下的。"},{"type":"say","who":"丁奉","text":"臣在知道陛下心意之前，就已经和骠骑将军施绩和吴郡陆家的柴桑督陆抗联络上。"},{"type":"say","who":"丁奉","text":"他们也表示随时愿意为大吴铲除奸臣了。"},{"type":"say","who":"孙休","text":"施绩先不说，陆抗…他行吗？"},{"type":"say","who":"丁奉","text":"陛下，这次的行动没他可不行，臣可以收拾掉孙綝本人，但是要一瞬间收拾掉他其他的兄弟党羽，就只能靠他了。"},{"type":"say","who":"孙休","text":"好，那么一切就交给你了。孙綝的末日建业宴会厅"},{"type":"say","who":"孙綝","text":"（建业到处传说这场腊八大祭，将会有巨变。我也认为有问题，本来想装病不来，却被陛下架著过来。）"},{"type":"say","who":"孙綝","text":"（现在我安排好大量部队在外面等候，并且算好时间就在我家放火，到时我就可以藉口救火，离开这里。）"},{"type":"say","who":"孙休","text":"丞相，好好的美酒佳肴，别浪费了。"},{"type":"say","who":"孙綝","text":"当然当然。"},{"type":"say","who":"孙綝","text":"对了，为什么左将军会在这个地方？"},{"type":"say","who":"丁奉","text":"我常年在外打仗，很少参加这样的庆典，今天算是来开开眼界的。"},{"type":"say","who":"孙綝","text":"原来如此。（我多心了？一个老头也没多大威胁吧？）士兵禀报皇上，丞相他家失火了，现在正在全力灌救中。"},{"type":"say","who":"孙休","text":"好，朕知道了，你也快去加入救火的行列吧。"},{"type":"say","who":"孙綝","text":"圣上，我家失火了，我得赶快回家帮忙救火才行呀。"},{"type":"say","who":"孙休","text":"外面部队很多，一点小火，丞相何需烦恼？"},{"type":"say","who":"孙綝","text":"不行呀，我家里面有很多宝贝等著我去救。"},{"type":"say","who":"孙休","text":"看来你是执意要走？"},{"type":"say","who":"旁白","text":"▶ 是的。"},{"type":"say","who":"孙休","text":"你的警觉心似乎比诸葛恪高一些，五年前诸葛恪还浑然不知自己将死。"},{"type":"say","who":"孙綝","text":"什么？！你想做什么？"},{"type":"say","who":"孙休","text":"丁奉！擒贼就趁现在！"},{"type":"say","who":"丁奉","text":"呵呵呵，你孙丞相底下部队众多，但当你只有一个人的时候，可完全不是我的对手。"},{"type":"say","who":"孙綝","text":"孙休！你敢算计我？"},{"type":"say","who":"孙休","text":"你这国贼，为什么不能算计你？"},{"type":"say","who":"孙綝","text":"哼，我麾下何止千万，外面还有我的卫队以及手握重兵的弟弟们。你杀了我，这些人绝对会造反。"},{"type":"say","who":"甘宁","text":"你说的那些卫队，是倒在外面的那群废物吗？"},{"type":"say","who":"陆抗","text":"征北将军陆抗救驾来迟，还请皇上恕罪。"},{"type":"say","who":"孙綝","text":"不可能吧，我带的卫队超过五千？"},{"type":"say","who":"甘宁","text":"五千个垃圾又能起到什么作用？只要清掉带头的人就好了。"},{"type":"say","who":"孙綝","text":"这是…孙恩的人头？你…"},{"type":"say","who":"陆抗","text":"不只是孙恩，孙据、孙干和孙闿也都已经伏法了。"},{"type":"say","who":"孙綝","text":"不可能呀，我来腊八大祭不到一个时辰，明明我还有看到弟弟们的。"},{"type":"say","who":"甘宁","text":"虽说要我一个时辰内杀掉那么多高官有点棘手，但也不是完全做不到。"},{"type":"say","who":"孙綝","text":"可恶啊，我哪点对不起你们吴郡陆家？我也没有亏待你这甘宁后人呀！"},{"type":"say","who":"陆抗","text":"当你杀害朱异的那刻，就注定我们南方人要和你翻脸了。"},{"type":"say","who":"陆抗","text":"昨天你可以杀朱异，今天你就可以杀我陆家人，我不能不先做反击。"},{"type":"say","who":"甘宁","text":"我是甘家继承甘宁名号的人，凭你一点小恩小惠，就足够买到我“锦帆贼”的效忠？"},{"type":"say","who":"孙綝","text":"陛下，不要杀我！我愿意被流放交州。"},{"type":"say","who":"孙休","text":"你为什么不把吕据和滕胤流放到交州？"},{"type":"say","who":"孙綝","text":"那…我愿意当官奴。"},{"type":"say","who":"孙休","text":"你又给吕据和滕胤当官奴的机会了？"},{"type":"say","who":"孙綝","text":"不要啊，不要啊！公元二五八年十二月，孙休发动政变，斩杀孙綝，并且屠灭其三族。孙休再挖出孙峻的棺材，取出殉葬印信，再砍薄棺木掩埋。孙峻一族的政治势力就此消亡，孙休正式掌握到权力。东吴新政建业皇宫"},{"type":"say","who":"孙休","text":"朕实在是太开心了，能够诛杀逆贼孙綝，靠的全是各位的功劳。"},{"type":"say","who":"张布","text":"不，这是圣上英明果断，我们作臣子的只是追随您的脚步而已。"},{"type":"say","who":"孙休","text":"因为孙峻和孙綝两位奸臣而死的人，朕都要将他们改葬，包括滕胤、吕据和诸葛恪等人。"},{"type":"say","who":"濮阳兴","text":"诸葛恪毕竟功在国家，其实圣上应该考虑要为他立碑纪念。"},{"type":"say","who":"鲁淑","text":"（这个人是谁呀？）"},{"type":"say","who":"薛莹","text":"（混在我们中间骗吃骗喝可以吗？）"},{"type":"say","who":"濮阳兴","text":"（嘿嘿，包个大工程就可以污钱污到饱，超爽的。）"},{"type":"say","who":"孙休","text":"朕知道濮阳卿家的心意，不过诸葛恪在炎热的夏天出动大军，让士兵死伤惨重，却没有半点功劳，不能算是有才能。"},{"type":"say","who":"孙休","text":"受到先帝重托，却死在一群小人之手，不能算是有智谋。立碑之事，请勿再议。"},{"type":"say","who":"濮阳兴","text":"（可惜了，本来要污他一大票的。）"},{"type":"say","who":"孙休","text":"这次有功劳的人，朕都有封赏。"},{"type":"say","who":"孙休","text":"左将军丁奉，升为大将军，加左右督护。"},{"type":"say","who":"孙休","text":"骠骑将军施绩，升为上大将军，都护督，担任西陵的守备工作。"},{"type":"say","who":"孙休","text":"镇北将军陆抗，升任镇军将军，和施绩共同督西陵。"},{"type":"say","who":"孙休","text":"至于甘宁…朕实在很想封你什么，你想不想成为大吴第一个有将军号的女子？"},{"type":"say","who":"甘宁","text":"我没什么兴趣耶，带兵打仗我不行，就让我跟随陆抗到西陵去吧！"},{"type":"say","who":"孙休","text":"既然这是你的心愿，那么朕就答应你。"},{"type":"say","who":"孙休","text":"至于辅义将军张布，朕封你为左将军，加中军督。"},{"type":"say","who":"虞汜","text":"（果然圣上最信任的是张布，还让他当到能掌管贴身护卫的中军督。但问题是另一个卫将军的位子会是谁的呢？）"},{"type":"say","who":"孙休","text":"卫将军的位子，朕决定要让一位新人来担任…会稽太守濮阳兴！"},{"type":"say","who":"濮阳兴","text":"臣必为陛下效死！"},{"type":"say","who":"陆凯","text":"（就是刚才那个耍宝的家伙？！）"},{"type":"say","who":"陆抗","text":"（本来以为碰到了明君，没想到他居然会重用这种人。）"},{"type":"say","who":"甘宁","text":"（陆抗，一个被压迫了这么多年的人，他不可能会信赖其他外人的。）"},{"type":"say","who":"陆抗","text":"（看来似乎又给你说对一件事情了。）君臣之缘姜维军营帐"},{"type":"say","who":"姜维","text":"邓艾居然防备得这么密不透风，一点可乘之机都没有。"},{"type":"say","who":"姜维","text":"绕道出兵关中，要面对的敌人更难缠，所得更少，就算打胜也得面对敌人中军，根本无法达到支配的目的。"},{"type":"say","who":"姜维","text":"如果回头出兵陇西，段谷之战在当地造成的影响，也不是短短几年就可以消除。"},{"type":"say","who":"姜维","text":"不，应该还是有机会，邓艾终究是人，不可能完全没有空隙。"},{"type":"say","who":"诸葛果","text":"主公，果来为您分忧解劳了。"},{"type":"say","who":"姜维","text":"我是不是最近太疲倦，开始产生幻觉了？"},{"type":"say","who":"诸葛果","text":"听到主公的召唤，又岂能不赶快回到主公的身边来。"},{"type":"say","who":"姜维","text":"真的是你？"},{"type":"say","who":"诸葛果","text":"虽然经历一些小小波折，但总算是回来。"},{"type":"say","who":"姜维","text":"你为什么要做这样危险的事情？"},{"type":"say","who":"诸葛果","text":"这是下仆应该尽的义务，请不要在意。"},{"type":"say","who":"姜维","text":"不行，怎么能叫我不在意呢！因为我的过失，让你必须要冒这么大的危险深入敌境，我欠你实在太多了。"},{"type":"say","who":"诸葛果","text":"主公不可以用亏欠这种字眼，您并没有做错任何事情。"},{"type":"say","who":"姜维","text":"你应该见到了诸葛诞吧，他到底是什么样的人？既然是丞相的族弟，应该是个忠臣吧。"},{"type":"say","who":"诸葛果","text":"不，他就是个一般人而已，会有私欲会害怕会犹豫。不过，他的最后很精采，这样也就够了。"},{"type":"say","who":"诸葛果","text":"别人看主公也是这样，但请主公不要勉强自己，硬要达到别人的期望。"},{"type":"say","who":"姜维","text":"你真是不可思议，什么事情几乎被你两眼就看穿了。"},{"type":"say","who":"诸葛果","text":"有任何事情，主公都可以问我，请主公不要客气。"},{"type":"say","who":"姜维","text":"现在要出兵比过往困难多了，短时间之内很难发兵，我担心敌人会在这空档进攻。"},{"type":"say","who":"姜维","text":"因此，我在规划一个大计，一个足以扭转一切的大计。"},{"type":"say","who":"诸葛果","text":"主公请说。"},{"type":"say","who":"姜维","text":"我认为过去魏延或王平将军的守备方式，实兵诸围以御外敌，虽合周易“重门”之义，却难以获得重大战果。"},{"type":"say","who":"姜维","text":"应该要让敌人进入，然后进行坚壁清野的战术，退守汉、乐二城。"},{"type":"say","who":"姜维","text":"敌人一旦进入平原，我们各城严密防守，再派出机动部队游击。"},{"type":"say","who":"姜维","text":"敌人攻城不下，郊外又抢不到粮食，补给线自然无法维持。"},{"type":"say","who":"姜维","text":"等撤退之日，各城同时出击，加上机动部队的力量，足够让敌军全军覆没，这就是所谓的歼敌战略。"},{"type":"say","who":"诸葛果","text":"确实是杰出的战略，主公真是了不起。"},{"type":"say","who":"诸葛果","text":"不过…"},{"type":"say","who":"姜维","text":"不过什么？"},{"type":"say","who":"诸葛果","text":"没什么，大概是果多心了…刘禅接受姜维的建议，命汉中督胡济退防汉寿。监军王含退守乐城，而护军蒋斌则撤退到汉城。又于西安、建威、武卫、石门、武城、建昌、临远等据点皆立围守。然而，却有些罕无人至的地方…武将的意气涪县蜀汉军军营"},{"type":"say","who":"句扶","text":"实在是太厉害了，居然和我打得不相上下，想不到短短时间内有这么大的进步。"},{"type":"say","who":"傅佥","text":"没错吧，我就说过他回来之后完全不一样了吧。"},{"type":"say","who":"蒋舒","text":"（确实不太一样，总感觉连长相都变了。）"},{"type":"say","who":"蒋舒","text":"莫非也是因为文鸯？"},{"type":"say","who":"赵统","text":"你怎么知道？"},{"type":"say","who":"傅佥","text":"只要看过文鸯战斗一次，恐怕一辈子都不会忘掉那样的场面。"},{"type":"say","who":"赵广","text":"那个家伙固然神勇，但却是个心术不正的人。"},{"type":"say","who":"傅佥","text":"心术不正？他明明很正直淳朴呀，在乐嘉大战之时，还要我们先撤退。"},{"type":"say","who":"赵统","text":"不，他在混战的时候投降司马昭，让寿春的守备整个崩溃。"},{"type":"say","who":"傅佥","text":"他投降司马昭？这么说未来我们有机会碰到他？"},{"type":"say","who":"柳隐","text":"这听起来似乎不是什么好消息。"},{"type":"say","who":"句扶","text":"怕什么，我会打不过那个小毛头？"},{"type":"say","who":"赵统","text":"虽说他是因为父亲文钦被诸葛诞杀害，走投无路才投奔司马昭。"},{"type":"say","who":"赵统","text":"但是我和他交手的时候，完全没有感受到一点的犹豫，甚至我认为他在期盼这样的事情发生。"},{"type":"say","who":"傅佥","text":"不可能的，文鸯都让司马师受惊身亡，怎么可能会愿意投奔司马家，那一定是有什么误会！"},{"type":"say","who":"蒋舒","text":"不，这也不一定，人遇到这种性命交关的时候，表现出和平时不一样的性格也是很正常的。"},{"type":"say","who":"赵广","text":"难道说你碰到性命交关的时候，也会作出那样的决定？"},{"type":"say","who":"柳隐","text":"反正文鸯又不一定会出现在我们面前，那种怪物，司马昭用起来大概也会有些顾忌吧。"},{"type":"say","who":"赵广","text":"这样说也是有道理，叛将的下场总不会好的。"},{"type":"say","who":"赵统","text":"不用担心，下次见到文鸯，我一定会亲手要他的性命！"},{"type":"say","who":"句扶","text":"好志气，这种气魄才像是赵云的儿子。"},{"type":"say","who":"傅佥","text":"别忘记我，我也很想和他交手呀！"},{"type":"say","who":"柳隐","text":"论武艺，或许老大或小句甚至杨姑娘应该都可以和他匹敌吧。"},{"type":"say","who":"蒋舒","text":"（真是一些愚蠢的武人，真正作战的时候，个人武艺又能影响什么大局？）"},{"type":"say","who":"蒋舒","text":"（文鸯再厉害，终究还是无法阻止毌丘俭的溃败。邓艾武艺并非顶尖，但也让大将军屡次受挫，这才是真正的武将！）"},{"type":"say","who":"赵广","text":"（大哥现在变得和以前完全不一样，但是我呢？我却没办法作出任何改变，难道我真的只能继续这样丢父亲的脸？）羌人之心涪县附近"},{"type":"say","who":"王嗣","text":"杨姑娘居然不去陪大将军，却来找我这个无用文人，还真是希奇。"},{"type":"say","who":"杨兰","text":"你居然会精通羌语，而且还能精准抓到我属于哪个部族。"},{"type":"say","who":"王嗣","text":"呵呵呵，我经营对羌人的关系这么多年，这点进步都只是小意思而已。"},{"type":"say","who":"杨兰","text":"姜维那边有诸葛果照顾他，我可以稍微放心一点，这段时间我也独占够久了。"},{"type":"say","who":"杨兰","text":"可是我担心的是，这次秦川之战因为对地理的不熟悉，反而让邓艾倒打一把，看来那里根本不是用兵的地方。"},{"type":"say","who":"王嗣","text":"我同意，本来我们的兵力就趋于劣势，若不能依靠对地理的熟悉和羌人帮助，就没有办法扳回原来的劣势。"},{"type":"say","who":"杨兰","text":"所以我想，应该合你我之力，重新争取羌人的支持才行。"},{"type":"say","who":"王嗣","text":"这点我也同意，虽说现在羌人普遍对我们不信任，但是并非努力不能克服的事情。"},{"type":"say","who":"杨兰","text":"可是你也知道我们羌人的个性，就算今天答应，明天也可能反悔。"},{"type":"say","who":"杨兰","text":"外人看我们认为是摇摆不定，毫无信义。但是…"},{"type":"say","who":"王嗣","text":"因为羌人处在那样恶劣的环境下，活得了今天不一定活得了明天，所以他们根本就没有未来的概念。"},{"type":"say","who":"杨兰","text":"你真的很厉害，难怪姜维会那么看重你。"},{"type":"say","who":"王嗣","text":"我认为还是有办法，你就把这一切都交给我吧。"},{"type":"say","who":"杨兰","text":"为什么？我也是羌人，可以帮你忙的，我还有认识很多羌人首领。"},{"type":"say","who":"王嗣","text":"好好把握自己的幸福吧，你可是我看过少数还有未来概念的羌人。"},{"type":"say","who":"杨兰","text":"咦？！"},{"type":"say","who":"王嗣","text":"好好把握自己的未来，你只要能过得像现在这样光鲜亮丽，我就可以用你作为范本，给其他羌人新的观念。"},{"type":"say","who":"杨兰","text":"原来如此…你真是个好人…"},{"type":"say","who":"王嗣","text":"喂，就算我有妻小，听到你这样的美女说我好人，我还是会伤心的。恍如梦幻司徒许靖墓"},{"type":"say","who":"陈祗","text":"现在我眼前已经没有任何政敌，圣上对我极度信任，姜维又和我连成一线，整个大汉几乎都在我的掌握中。"},{"type":"say","who":"陈祗","text":"现在我还有什么敌人呢？哈哈哈，外祖父，您看到了吗？"},{"type":"say","who":"陈祗","text":"因为您的栽培，我才会有今天，我真的很感激您当日对我的照顾。"},{"type":"say","who":"陈祗","text":"然而您却因为舍弃刘璋那样的昏君，而背负著恶名，让先帝看轻您，却忽略您是和华歆或是王朗齐名的名士。"},{"type":"say","who":"陈祗","text":"当时我听到先帝对您的评语，我好恨自己没有能力帮您争口气。"},{"type":"say","who":"陈祗","text":"您虽然当到司徒，但是背后却有多少人在嘲笑您徒具虚名，而您却只是微笑不语，我真的好恨自己的没用。"},{"type":"say","who":"陈祗","text":"于是我决定，我要用一切手段爬到最高的位子，让那些只会在背后嘲笑别人的蠢人好看。"},{"type":"say","who":"陈祗","text":"哪怕是我背负著奸臣的恶名，我也要成为人上人，让别人连看轻我的胆量都没有。"},{"type":"say","who":"陈祗","text":"呜…咳咳咳…（吐血）"},{"type":"say","who":"陈祗","text":"不会吧…就差这一步…为什么老天不给我这个机会？"},{"type":"say","who":"陈祗","text":"难道我多年的奋斗，终究就是梦一场？公元二五九年八月，蜀汉尚书令陈祗得到急病病倒，得到消息的刘禅立刻放下手边的事情前去探望。陈祗之死成都尚书令府"},{"type":"say","who":"黄皓","text":"皇上，您已经三天没有用膳了，多少也吃一点吧。"},{"type":"say","who":"刘禅","text":"看到尚书令变成这样，朕哪有心情去做别的事情？"},{"type":"say","who":"黄皓","text":"奴才很明白皇上的心情，但是您的身体还是要顾好呀。"},{"type":"say","who":"刘禅","text":"呜呜呜，在朕二十七岁以前，朕是个完全的傀儡，相父要朕做什么，朕都没有想过有一点意见。"},{"type":"say","who":"刘禅","text":"当时朕从来没有认为这样的日子不好，直到尚书令的出现。"},{"type":"say","who":"刘禅","text":"他告诉朕，朕是人，不是任何人可以控制的，更不是相父的工具。"},{"type":"say","who":"刘禅","text":"从那天起，朕才知道自己该过什么样的生活，才知道要去找回属于自己身为人的尊严。"},{"type":"say","who":"黄皓","text":"奴才都不知道这些事情，原来尚书令他那么伟大。"},{"type":"say","who":"陈祗","text":"陛下…微臣已经不能陪您了…"},{"type":"say","who":"刘禅","text":"你说什么话？朕命令你起来，朕命令你马上康复！"},{"type":"say","who":"陈祗","text":"请让微臣一辈子就违抗您这么一次吧…微臣虽然也很恨上天不给我多点时间，但既然是天意，也只能接受…"},{"type":"say","who":"刘禅","text":"呜呜呜…为什么上天要从朕手上夺走这样的忠臣？这有天理吗？"},{"type":"say","who":"陈祗","text":"陛下，微臣并没有您想像得那么好，微臣也在您背后作了很多不乾净的事情。"},{"type":"say","who":"刘禅","text":"那又如何？你和黄皓是少数肯把朕当作是人在看的，光是这点，就足够抵掉你做过的所有坏事！"},{"type":"say","who":"刘禅","text":"别人夸赞相父有才能有操守，但在朕看来，相父还远不如你。"},{"type":"say","who":"陈祗","text":"呵呵呵…微臣能够超越丞相？有您说的这句话就够了…微臣真的已经满足了。"},{"type":"say","who":"陈祗","text":"陛下，在临走前，微臣请您一定要处理好姜维的事情。"},{"type":"say","who":"刘禅","text":"姜维就只是个专心于打仗的武人，有那么重要吗？"},{"type":"say","who":"陈祗","text":"他的军事才能，绝对是我大汉顶尖的，也只有他才可以对抗曹贼。"},{"type":"say","who":"陈祗","text":"然而若是他被篡逆之贼利用或是心生叛逆，却也是我大汉最可怕的祸患。"},{"type":"say","who":"陈祗","text":"所以微臣用尽了方法，让他能够为陛下所用，却又被群臣孤立。"},{"type":"say","who":"陈祗","text":"然而在微臣死后，恐怕其他人不能理解这样的想法，只想把他除之后快。"},{"type":"say","who":"陈祗","text":"只怕到时候把姜维逼急，让他谋叛或是投靠曹贼，对我们大汉都不是好事。"},{"type":"say","who":"刘禅","text":"朕知道，朕会照办的。"},{"type":"say","who":"陈祗","text":"（其实我最担心的就是黄皓，我为了要彻底取得陛下信任，只好和他合作，结果放纵他一步步扩大势力。）"},{"type":"say","who":"陈祗","text":"（如果我不在了，黄皓的势力将更没有人可以控制，我真是留下了个大患。）"},{"type":"say","who":"陈祗","text":"（只是当初皇上大权在握，我如果不和黄皓联合，又怎么能取得信任？这根本就是两难呀。）"},{"type":"say","who":"陈祗","text":"（伯约，在我死后，你可千万不要有什么太大的动作。否则引起黄皓不满，陛下也会立刻猜疑你的。）"},{"type":"say","who":"陈祗","text":"这样…微臣也没有什么遗憾了…"},{"type":"say","who":"黄皓","text":"（我正开始嫌陈祗这家伙碍事，没想到老天就帮了我这个大忙。）"},{"type":"say","who":"黄皓","text":"（反正继任人不外乎诸葛瞻或是樊建，这些人都没什么了不起的。只要不要和他们起太大冲突就不会有事情。）"},{"type":"say","who":"黄皓","text":"（至于那个姜维，不过一介武夫，为什么陈祗要这么看重他？若是要为他和大汉多数人冲突，这不是很笨的事情？）公元二五九年八月二十日，蜀汉尚书令陈祗病逝。他工于心计，精于谄媚，受到皇帝刘禅的信任。虽然官位在姜维之下，但因为姜维经常出外作战，很少过问中央政事，权力和受到的信任还不如陈祗。陈祗死后，刘禅深感痛惜，为他放声大哭后下诏：“祗统职一纪，柔嘉惟则，干肃有章，和义利物，庶绩允明。命不融远，联用悼焉。夫存有令问则亡加美諡，谥曰忠侯”。拜访成都镇军大将军府"},{"type":"say","who":"廖化","text":"德艳，你知道这个消息吗？丞相的公子和龚袭、长元已经内定掌理朝政，我们不妨去拜访他们吧。"},{"type":"say","who":"廖化","text":"他们和我们一样都是荆襄人，绝对不会亏待我们的。"},{"type":"say","who":"宗预","text":"我们都年过七十了，今生能求的都已经求了，只差一死而已，何必主动去拜访年轻人？要去你自己去吧。"},{"type":"say","who":"廖化","text":"德艳，你难道不明白我的意思？"},{"type":"say","who":"宗预","text":"我当然知道，但可惜在这里我不会和你站在同一阵线，我对伯约没有意见。"},{"type":"say","who":"宗预","text":"只是没想到过去一向支持北伐的你，会跑去和张翼、谯周等人混在一起。"},{"type":"say","who":"廖化","text":"那是因为我要守护关将军想要守护的大汉。"},{"type":"say","who":"宗预","text":"那就怪了，关将军过去也是用北伐来守护大汉，为什么现在你要反对姜维的北伐？"},{"type":"say","who":"廖化","text":"姜维的穷兵黩武已经害到我大汉了，他根本就不是为了大汉在北伐，而是为个人的名位。"},{"type":"say","who":"宗预","text":"我可不这么认为，他如果真的为了保全自己的名位，多得是比北伐更有效率的办法。"},{"type":"say","who":"宗预","text":"你真认为伯约会不如孙綝或是司马昭？"},{"type":"say","who":"廖化","text":"既然你没有意愿就算了。"},{"type":"say","who":"廖化","text":"告诉你！我宁愿牺牲自己一切的尊严，也要爬到可以主宰军事的位子。"},{"type":"say","who":"廖化","text":"从丞相病逝后，你看看大汉的主政者是什么德行？"},{"type":"say","who":"廖化","text":"不是像蒋琬或费祎那样的软弱者，就是像姜维那样的好战狂。"},{"type":"say","who":"廖化","text":"有人像关将军那样对大汉一片赤诚，为了大汉忘记自己的利害得失？没有！"},{"type":"say","who":"廖化","text":"现在的大汉，早就已经失去开国的精神，这样下去一定会亡国。"},{"type":"say","who":"廖化","text":"所以我要改变这一切，而唯一的方法就是爬上去，爬到足以主宰一切的位子。"},{"type":"say","who":"宗预","text":"你太偏激了，这样和眼中只有先帝的关将军有什么差别？"},{"type":"say","who":"廖化","text":"像关将军有什么不好？只有他才是我们大汉武将的典范！"},{"type":"say","who":"宗预","text":"你的偏见蒙蔽了你的双眼，难怪伯苗会拜托我一定要坚定自己的立场。"},{"type":"say","who":"宗预","text":"我希望你能冷静想想，姜维的奋斗到底是为了谁？没有姜维之后就会天下太平？新的掌权者成都皇宫"},{"type":"say","who":"刘禅","text":"尚书令不幸过世，朕到现在还是哀痛得食不下咽。"},{"type":"say","who":"刘禅","text":"不过，该做的人事安排还是要做好，不然就对不起尚书令的在天之灵。"},{"type":"say","who":"刘禅","text":"尚书仆射董厥升任尚书令，尚书诸葛瞻则升任尚书仆射，希望你们能继续奉宗未完成的志业。"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"诸葛瞻","text":"微臣一定会像父亲那样效忠陛下。"},{"type":"say","who":"诸葛瞻","text":"（终于等到陈祗这个奸臣死了，这下子还有谁可以保护姜维你这个奸贼？）"},{"type":"say","who":"诸葛瞻","text":"（等著吧，我一定会罢免掉你大将军的位子，让姊姊回到家里，不要再过这种没有希望的日子了。）"},{"type":"say","who":"刘禅","text":"另外，前任车骑将军夏侯霸战死沙场，朕哀痛万分，所以没有再派人接替这个位子。"},{"type":"say","who":"刘禅","text":"经过皇后的再三建议，朕还是决定要走出来，让车骑将军这个位子不再悬缺。"},{"type":"say","who":"刘禅","text":"廖化，朕封你为右车骑将军、假节，领并州刺史，封中乡侯。"},{"type":"say","who":"刘禅","text":"张翼，朕则封你为左车骑将军。"},{"type":"say","who":"廖化","text":"谢陛下！"},{"type":"say","who":"张翼","text":"臣张翼感谢陛下厚恩。"},{"type":"say","who":"廖化","text":"（终于让我爬到这个位子，这下我终于可以一展抱负了。）"},{"type":"say","who":"张翼","text":"（这下我终于有这个地位可以和姜维争辩，以我一个益州人能当到车骑将军，莫非"},{"type":"say","who":"旁白","text":"▶ 是在作梦？）"},{"type":"say","who":"宗预","text":"（元俭，这就是你想要的东西？为了这样的地位，去和年轻人低声下气，你认为关羽将军希望看见你变成这样？）洛阳宫殿潜龙诗"},{"type":"say","who":"郑冲","text":"之前在宁陵井中发现两条黄龙，而之前顿丘和阳夏等地的水井中，也不断发现黄龙，这正是吉祥的预兆。"},{"type":"say","who":"曹髦","text":"司徒呀，你可知道龙象徵君王，可他不但不能升天，还不能留在农田，只能委屈地掉在水井之中，这哪是什么祥兆？"},{"type":"say","who":"曹髦","text":"伤哉龙受困，不能跃深渊。上不飞天汉，下不见于田。"},{"type":"say","who":"曹髦","text":"蟠居于井底，鳅鳝舞其前。藏牙伏爪甲，嗟我亦同然。"},{"type":"say","who":"司马孚","text":"（就算我是司马家的人，我也不愿意看见圣上有如此悲苦的心境，侄儿真的做得太过份了。）"},{"type":"say","who":"陈泰","text":"（我认识的司马子上应该是个温厚而又善良的人，为什么他会把圣上搞成这样，你可以回答我吗？）"},{"type":"say","who":"王经","text":"（我从陇西回来洛阳之后，每天看到的都是这样的景象。司马昭，你这样还算人臣吗？）"},{"type":"say","who":"王沈","text":"（我可以装作没听到吗？我同情皇上的处境，但我没有勇气对抗司马昭，到底我该怎么办？）"},{"type":"say","who":"钟会","text":"（看来曹髦是不除不可了，大将军看到这首诗应该会明白该怎么做…就让他变曹芳第二吧。）司马昭的真意洛阳大将军府"},{"type":"say","who":"司马昭","text":"司空王文舒日前过世了，为了因应吴贼不断入侵，我决定在荆州设置两个新都督，以汉水为界分督南北。"},{"type":"say","who":"司马昭","text":"都督荆州交给王基，都督江北是州泰，江南则是陈骞。"},{"type":"say","who":"司马昭","text":"（王昶是最后一位经历高平陵政变的都督，更是我司马家背后的支柱，所以让他继续维持辖区。）"},{"type":"say","who":"司马昭","text":"（现在他死了，没必要再维持这么大的都督了。那样只会妨碍我司马氏而已。）"},{"type":"say","who":"司马昭","text":"（这样切割都督区，才能有效削弱那些可能反抗的异姓都督，并安插我的亲信。最后，就是让我司马氏尽据要地。）"},{"type":"say","who":"钟会","text":"这是今天朝会，圣上做的一首诗，请您过目。"},{"type":"say","who":"司马昭","text":"蟠居于井底，鳅鳝舞其前。藏牙伏爪甲，嗟我亦同然。"},{"type":"say","who":"司马昭","text":"这样的诗怎么看都是针对我吧。"},{"type":"say","who":"钟会","text":"我认为大将军不能不提防，万一再发生曹芳要胁持您的事情就不好了。"},{"type":"say","who":"钟会","text":"不如就用对付曹芳的方式，来让曹髦下台吧。"},{"type":"say","who":"裴秀","text":"现今圣上又没有失德之举，擅自废黜恐怕会让天下人心不服。"},{"type":"say","who":"裴秀","text":"（钟会你这个混蛋，你连陛下和你一起讨论学问的感情都不顾？）"},{"type":"say","who":"裴秀","text":"（我裴秀再怎么无耻，至少还记得陛下称我为儒林丈人时的感动呀。）"},{"type":"say","who":"荀顗","text":"我也认为不妥，当时大将军废黜了曹芳，结果惹来了毌丘俭反叛，现在若是再一次废帝，不知道会出什么乱子。"},{"type":"say","who":"钟会","text":"毌丘俭不过是为了个人野心才起兵，和大将军的废君有何关系？"},{"type":"say","who":"钟会","text":"难道要放任无道之君不管，辜负大家对大将军行伊尹霍光之事的期待？"},{"type":"say","who":"贾充","text":"我也同意士季的看法，圣上现在年幼就表现出强烈的反抗心，等到长大恐怕会更难以应付。"},{"type":"say","who":"司马昭","text":"仲容，你马上就要去外地赴任。听说你之前见过圣上，感觉如何？"},{"type":"say","who":"石苞","text":"非常人。"},{"type":"say","who":"石苞","text":"（年纪轻轻却对钱和女人没什么兴趣，真不是一般人呀。）"},{"type":"say","who":"司马昭","text":"嗯…像士季或是公闾这样为我设想，我实在是很感动。"},{"type":"say","who":"司马昭","text":"不过，虽然说圣上如此看我，作臣子的又能如何呢？"},{"type":"say","who":"司马昭","text":"就算是伊尹或是霍光，也是君王先有失德之事，才在没有选择的情况下作出这样的事情。"},{"type":"say","who":"司马昭","text":"他们可是为了天下苍生才敢如此不怕遭人非议。"},{"type":"say","who":"司马昭","text":"我年纪也不小了，欲望却越来越小，只求能够在有生之年继续为大魏尽忠就好。"},{"type":"say","who":"司马昭","text":"也希望圣上能体会我这卑微的想法，停止对臣的猜忌才好。"},{"type":"say","who":"司马昭","text":"不然再这样继续下去，我怕圣上会因此走上昌邑王或是太甲的歧途呀。"},{"type":"say","who":"贾充","text":"（意思是说，如果圣上真的变成昌邑王或是太甲的话，还是要废君？）"},{"type":"say","who":"钟会","text":"（看来公闾还是不懂，大将军真正的意思，是要我们制造圣上变成昌邑王或是太甲的事实。）恶梦伊水魏军营帐外"},{"type":"say","who":"桓范","text":"曹真一代英雄，生你们这些兄弟，一群猪猡！想不到今天我要陪你们全家被屠灭。"},{"type":"say","who":"桓楷","text":"爹，事情不一定会变成那样吧…司马懿不是已经指著洛水发誓了？"},{"type":"say","who":"桓范","text":"司马懿说的话可以信，屎都可以吃了。"},{"type":"say","who":"桓范","text":"我自认智谋不输司马仲达，由于计谋不被采纳才使那家伙成名。"},{"type":"say","who":"桓范","text":"大将军、蒋太尉、高司徒都相信司马懿不会对我们赶尽杀绝，他们都太天真了。"},{"type":"say","who":"桓范","text":"猛虎伏地，为的是扑杀猎物。司马懿卧病两年，一朝奋起，怎么可能放过我们！"},{"type":"say","who":"桓范","text":"我与曹爽关系密切，又从京师逃来投奔天子，绝对会被清算。我太了解那个人的个性了。"},{"type":"say","who":"桓范","text":"你的官位低、名声浅，认识你的人不多。趁现在天子与大将军尚未回城，你赶快逃！"},{"type":"say","who":"桓楷","text":"我们谯国桓氏经学传家，自汉明帝开始一共教授五世汉帝。"},{"type":"say","who":"桓楷","text":"从前党锢之祸，名士以死义为荣。更何况当时若不是孩儿要您不要接受司马懿的任命，岂有今日之祸。"},{"type":"say","who":"桓楷","text":"不论如何，孩儿都不能能做出舍弃父亲的不孝之行。"},{"type":"say","who":"桓范","text":"我受曹爽照顾，今天陪他到底，是表现忠与义。"},{"type":"say","who":"桓范","text":"但是你和曹爽没有这层关系，陪我死是愚蠢，因此将先祖桓荣公的血脉断绝，更是大不孝。"},{"type":"say","who":"桓范","text":"延续谯国桓氏的血脉，为先人复仇，再续五世帝师的荣耀，才是大孝。快走！再慢就来不及了！"},{"type":"say","who":"桓楷","text":"父亲，四处风声鹤唳，我该逃往何方？"},{"type":"say","who":"桓范","text":"还记得我提过的那个狂士吗？"},{"type":"say","who":"桓范","text":"那个跟我一样自大的狂人，虽然还没表明立场，但以他的婚姻与气节，绝对不会投向司马家的。"},{"type":"say","who":"桓楷","text":"孩儿明白了，请您多保重。"},{"type":"say","who":"桓范","text":"你也保重！"},{"type":"say","who":"桓范","text":"子丹，或许再过不久我也要去见你了。"},{"type":"say","who":"桓范","text":"我无法保护你的儿子，只能用陪他到底的方式向你谢罪了。"},{"type":"say","who":"桓范","text":"楷儿，父亲无能，只能想出用这种方式来让你愿意继续活下去。"},{"type":"say","who":"桓范","text":"希望先祖英灵保佑你躲过司马懿的追捕。智囊之子山阳嵇府"},{"type":"say","who":"嵇康","text":"又是那个恶梦？"},{"type":"say","who":"桓楷","text":"这十年来，我每晚都梦到那一天。"},{"type":"say","who":"桓楷","text":"为了逃生，我让自己容貌憔悴邋遢，只怕别人认出我来。"},{"type":"say","who":"桓楷","text":"但最让我遗憾的是，现在司马懿已死，我再也无法手刃仇敌，为父报仇。"},{"type":"say","who":"嵇康","text":"看来你长进了不少，刚来这边的时候，你还一直吵著要报仇。"},{"type":"say","who":"桓楷","text":"过去的我太傻了，以我一个人的力量怎么可能和整个司马家对抗。"},{"type":"say","who":"嵇康","text":"复仇之前，必须先累积足够的力量。"},{"type":"say","who":"嵇康","text":"一个人的力量虽然不够，但是许多人一起合作的话就大不相同。"},{"type":"say","who":"嵇康","text":"这几天我接到一个消息，有个你一定要见的人会赶来山阳这边，请你要先有心理准备。曹绫的交代洛阳宫殿"},{"type":"say","who":"曹髦","text":"姑姑，为什么这个时候要离开洛阳？朕正是需要你的时候。"},{"type":"say","who":"曹绫","text":"我曹家的大长辈，也是前汉王朝最后一任皇后病危，我必须得去见她最后一面。"},{"type":"say","who":"曹髦","text":"可是姑姑，没有必要亲自过去呀，她是这么重要的人？"},{"type":"say","who":"曹绫","text":"你年纪还小，不知道我们曹家亏欠她有多少，她是这个时代最可怜的牺牲品。"},{"type":"say","who":"曹绫","text":"你现在手上的玉玺有两个缺角，新的那个缺角就是她把玉玺摔到地上造成的。"},{"type":"say","who":"曹绫","text":"当面对父皇穷凶恶极的追讨时，她只能用这个方法来表示抗议。"},{"type":"say","who":"曹髦","text":"原来她也和朕一样…"},{"type":"say","who":"曹绫","text":"我不在洛阳的时候，请千万要小心，不要因为司马昭而有任何冲动的行为。"},{"type":"say","who":"曹髦","text":"放心吧，朕已经年满二十，有能力去对抗司马昭。"},{"type":"say","who":"曹绫","text":"千万不要这样做，就像你之前做那个潜龙诗，除了刺激司马昭外，并没有任何正面效果。"},{"type":"say","who":"曹绫","text":"你是我曹家未来的希望，千万不要因为一时冲动而葬送了自己，知道吗？"},{"type":"say","who":"曹髦","text":"嗯…我知道。"},{"type":"say","who":"曹绫","text":"（皇上非常聪明，应该能理解我的意思。为什么我还是有种不安的感觉，但是我又不能不去山阳见姑姑最后一面。）"},{"type":"say","who":"曹绫","text":"（相信皇上吧，如果他可以在我不在的时候独自面对司马昭而不出事，以后我也不需要担心什么。）忍无可忍洛阳宫殿"},{"type":"say","who":"钟会","text":"臣钟会以为，大将军功德巍巍，应该成为三公之上的相国，封晋公，并且加九锡。"},{"type":"say","who":"曹髦","text":"过去大将军不是一再辞让，怎么今天居然主动向朕要求了？"},{"type":"say","who":"曹髦","text":"更妙的是，朕已经多久没有见过大将军的身影了，想不到今天可以得见。"},{"type":"say","who":"司马昭","text":"这是陛下对臣的误解，臣过去一直辞让这样的恩赐，今日也没有接受的打算。"},{"type":"say","who":"司马昭","text":"只是众意实在难违，过去武皇帝面对魏公这样的赏赐，也是在不得已的情况下就任的。"},{"type":"say","who":"曹髦","text":"呵呵呵，大将军居然已经准备和武皇帝相比了？"},{"type":"say","who":"司马昭","text":"不敢，如果认为臣的比喻有失当的地方，也恳请陛下责罚。"},{"type":"say","who":"曹髦","text":"你的五千甲士，朕可惹不起。"},{"type":"say","who":"贾充","text":"陛下，过去您对于大将军受封晋公一事，从来没有考虑过就同意，为何今日却显得不情愿？"},{"type":"say","who":"曹髦","text":"朕没有不同意，朕只是想问大将军一声，是否真的想要受封晋公？"},{"type":"say","who":"师纂","text":"陛下对于忠臣如此猜忌，这还是为君之道吗？"},{"type":"say","who":"王经","text":"你一个小小的主簿敢如此放肆，当朝堂上没有人了？"},{"type":"say","who":"师纂","text":"笑话，谁不知道你王尚书在洮西被蜀贼打得大败，丧师数万。"},{"type":"say","who":"师纂","text":"像你这种人都可以站在朝堂，还敢说朝堂有人？"},{"type":"say","who":"司马孚","text":"子上，你可以有点分寸吗？老夫虽然已经老眼昏花，但有些事情还是看得很清楚。"},{"type":"say","who":"司马昭","text":"师主簿，不要太过分了，我们毕竟都是大魏的臣子。"},{"type":"say","who":"旁白","text":"▶ 是…"},{"type":"say","who":"钟会","text":"我想陛下应该也不希望把场面弄得那么僵，其实解开僵局，都系在陛下的一念之间。"},{"type":"say","who":"曹髦","text":"你要朕怎么做？"},{"type":"say","who":"钟会","text":"臣不敢指导陛下该如何做，只是齐王的前例就在眼前，不得不慎呀。"},{"type":"say","who":"曹髦","text":"你敢公开要胁朕？来人！"},{"type":"say","who":"贾充","text":"不会有人来的，别忘记臣是中护军，而臣只听大将军的命令。"},{"type":"say","who":"贾充","text":"陛下，其实您要是早点答应的话，就不会有现在的冲突了。"},{"type":"say","who":"陈泰","text":"（子上，这就是你的回答吗？我的心在淌血啊！爹，请您告诉我该怎么办？）"},{"type":"say","who":"曹髦","text":"（真可悲呀，朕不但得被这些臣下要胁，甚至连叫个卫兵的叫不动。）"},{"type":"say","who":"曹髦","text":"（这种屈辱，朕可以忍受吗？要是不反击，朕对得起曹家列祖列宗？）"},{"type":"say","who":"曹髦","text":"（等一下，司马昭在笑？莫非他真正的目的是…）废帝阴谋洛阳大将军府"},{"type":"say","who":"钟会","text":"大将军，我保证皇上一定会和您翻脸的，请尽早做准备。"},{"type":"say","who":"司马昭","text":"在你们两位真正的心腹面前，我也不想说什么掩饰的话了。"},{"type":"say","who":"司马昭","text":"看见曹髦的表情，事情大概就已经成功了一大半。"},{"type":"say","who":"司马昭","text":"果然那小子没有曹绫在身边，什么蠢事都做得出来。"},{"type":"say","who":"钟会","text":"洛阳城内的禁军都被掌握住，陛下绝对不可能得到任何禁军的效忠。"},{"type":"say","who":"贾充","text":"我担任中护军，绝对会确保底下的将士不会轻举妄动。"},{"type":"say","who":"司马昭","text":"很好，这样那小子不管用什么方法，最终只会遭到我先发制人的反击。"},{"type":"say","who":"司马昭","text":"公闾，你就和五弟去召集军队，等候我的命令，随时准备包围皇宫。"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"司马昭","text":"哼哼哼，曹芳当时还能获得李丰或是许允的协助，现在朝中还有哪些人可以帮你？洛阳宫殿曹髦发难"},{"type":"say","who":"曹髦","text":"司马昭之心，路人皆知！"},{"type":"say","who":"曹髦","text":"朕不能坐在这里等候被他罢黜。今天，朕要和你们一起行动，讨伐司马昭。"},{"type":"say","who":"王经","text":"昔日鲁昭公不能忍受季孙氏专权，起而奋战，终于失败逃走，被天下人讥笑。"},{"type":"say","who":"王经","text":"而今，权力落在司马家已久，无论中央或是地方，都愿意为司马家效死。他们不懂逆顺的道理，并不是最近才如此。"},{"type":"say","who":"王经","text":"皇家的禁卫军人数不多，武器盔甲也十分脆弱，陛下用什么讨伐？"},{"type":"say","who":"王经","text":"一旦发动，岂不是让本来要被铲除的司马家势力更加强大？大祸深不可测，请陛下考虑。"},{"type":"say","who":"曹髦","text":"四年前，朕与侍中荀顗、尚书崔赞、袁亮、钟毓、给事中中书令虞松等讲述礼典，论及帝王优劣。"},{"type":"say","who":"曹髦","text":"诸臣认为汉高祖为优，朕却不同意此论，认为少康为优。"},{"type":"say","who":"曹髦","text":"这是因为朕想要效法少康，去讨伐像寒浞那样的奸臣。"},{"type":"say","who":"曹髦","text":"朕的主意已定，即使身死，又有什么好怕的？更何况不一定会死！"},{"type":"say","who":"王沈","text":"陛下起兵不可能成功的，我要向大将军报信。要不要一起来？"},{"type":"say","who":"王经","text":"你说什么？！"},{"type":"say","who":"王沈","text":"这是你我活命的最后机会，难道你想要像李丰或是夏侯玄那样？"},{"type":"say","who":"王经","text":"圣上对你我如此信任，将这样的大事相告。我不能追随陛下起兵，但也不可能出卖陛下的。"},{"type":"say","who":"王沈","text":"你真是傻，你自己想死没关系，你的家人呢？你要你的老母跟著你一起被杀？"},{"type":"say","who":"王经","text":"处道！我今天终于看清楚你这个人了！只可叹圣上居然看走眼，还把你当作像老师一样尊敬。"},{"type":"say","who":"王沈","text":"随便你怎么说，你出身寒微，和我太原王家要背负的东西完全不一样。"},{"type":"say","who":"王经","text":"这都是你的借口罢了，说到头你还是怕死，要去报信你自己去吧，我是不会去的。"},{"type":"say","who":"王沈","text":"唉…何必呢…洛阳太后寝宫道别"},{"type":"say","who":"曹髦","text":"母后，孩儿要出发了。"},{"type":"say","who":"郭太后","text":"难道我和你说那么多，都没办法让你回心转意？"},{"type":"say","who":"曹髦","text":"在这个时候，朕也只有挺身而战了。朕不想落得像齐王那样的下场。"},{"type":"say","who":"郭太后","text":"你知道我已经送走了几个皇帝？我最爱的明帝在我没有准备的时候离开了我。"},{"type":"say","who":"郭太后","text":"接著齐王在我眼前，被司马师活生生带走。"},{"type":"say","who":"郭太后","text":"现在你又急著去送死，为什么我这个做太后的要变成个送行者？"},{"type":"say","who":"曹髦","text":"司马家把您当成工具使唤，只要有什么旨意都用您的名义来发，根本没有过问您的意见，请问这种情况您还要忍？"},{"type":"say","who":"曹髦","text":"武皇帝率军横扫天下，破袁术、擒吕布、灭袁绍、败马超，何等威风。"},{"type":"say","who":"曹髦","text":"而如今朕却受制司马家，对比之下何等不堪。"},{"type":"say","who":"曹髦","text":"若是武皇帝站在朕的立场，一定会毫不考虑拔剑而战。"},{"type":"say","who":"郭太后","text":"曹家人的脾气都是一样的，我虽然没见过武皇帝，但是你和明皇帝真的很像。"},{"type":"say","who":"郭太后","text":"这也是我当初向司马师坚持要立你当皇帝的原因。"},{"type":"say","who":"许仪","text":"陛下，您不能去！"},{"type":"say","who":"曹髦","text":"怎么连许仪你都阻挡朕？"},{"type":"say","who":"许仪","text":"公主有交代过俺，不论如何都不能让陛下作出冲动的事情。"},{"type":"say","who":"曹髦","text":"原来姑姑还是安排了这一手…"},{"type":"say","who":"曹髦","text":"许仪，朕问你！过去壮侯许仲康在世的时候，如果武皇帝要出战，他会怎么样？"},{"type":"say","who":"许仪","text":"俺老爹当然是跟著一起杀出去。"},{"type":"say","who":"曹髦","text":"那么为什么你不和朕一起去讨伐司马昭？"},{"type":"say","who":"许仪","text":"这……"},{"type":"say","who":"曹髦","text":"你空有一身好武艺，却从来没有好好用过，现在正是用来铲除奸臣，报效大魏的时候。"},{"type":"say","who":"许仪","text":"可是…"},{"type":"say","who":"曹髦","text":"跟朕一起走吧，这样你才会真正成为超越“虎痴”的人。"},{"type":"say","who":"许仪","text":"俺愿意和陛下同生共死！"},{"type":"say","who":"曹髦","text":"母后，永别了…"},{"type":"say","who":"郭太后","text":"曹家的人为什么全都是傻瓜？公元二六零年五月，曹魏皇帝曹髦率领皇家卫士和奴仆等杂牌军，直向大将军司马昭的住所而去，准备讨伐他。激战洛阳东止车门"},{"type":"say","who":"司马伷","text":"这可不好玩呀，这个许仪跟怪物一样，只用一招就扫掉这么多人。"},{"type":"say","who":"司马伷","text":"再加上这个皇上也不弱，还真是麻烦。步兵我们该怎么办？继续攻击？"},{"type":"say","who":"司马伷","text":"你傻了？你敢杀皇帝？"},{"type":"say","who":"曹髦","text":"前面的人快点滚开！难道你们想要冒犯皇家？还是想要死在朕的剑下？"},{"type":"say","who":"曹髦","text":"不管是什么理由，阻挡朕的都将犯下叛逆大罪。步兵怎么办呀？！步兵我不想和那个大块头交战，更不想谋逆。"},{"type":"say","who":"司马伷","text":"（二哥也真没良心，这种里外不是人的任务竟然敢交给我。）"},{"type":"say","who":"司马伷","text":"（今天我虽然是二哥的血亲，但若是真被问起弑君大罪，难保不会被牺牲。）"},{"type":"say","who":"司马伷","text":"（更何况想到之前岳父大人的事情，到现在还是感觉有些毛毛的，怎么说我都娶了诸葛诞的女儿呀。）"},{"type":"say","who":"司马伷","text":"撤了撤了，我们实在是无法抵挡陛下强大的军队呀（棒读）。"},{"type":"say","who":"许仪","text":"陛下，咱们突破了司马伷的防守了。"},{"type":"say","who":"曹髦","text":"很好，这下应该没有军队可以阻挡朕了。"},{"type":"say","who":"曹髦","text":"司马昭，你洗干净你的脑袋等朕。最强的夫妇洛阳大将军府"},{"type":"say","who":"王元姬","text":"子上，你这样子给别人看到可不得了。"},{"type":"say","who":"王元姬","text":"自从你第一次进我闺房以来，就再也没露出过这么紧张的表情了。"},{"type":"say","who":"司马昭","text":"呼…曹髦这个臭小子真的摆了我一道，没想到他会这么绝，直接率领一堆杂牌军来攻击我。"},{"type":"say","who":"司马昭","text":"本来指望五弟把他挡下来，哪知道他居然当场跑掉，把这问题丢给我。"},{"type":"say","who":"王元姬","text":"你敢让圣上受伤？"},{"type":"say","who":"司马昭","text":"是呀，我好不容易爬到这一步，距离登基就只差一点点，怎么可以因为这个臭小子而坏了我的大事。"},{"type":"say","who":"司马昭","text":"现在我只能把希望寄托在贾充身上，我想知道花了这么多时间拉拢的人，在这紧要关头能否帮上忙。"},{"type":"say","who":"王元姬","text":"这就是你让他成为中护军的原因吧。"},{"type":"say","who":"司马昭","text":"虽然说我对外人无法信任，但是只有我们司马家的人也不足以成事，爹以前就这样叮嘱我们。"},{"type":"say","who":"王元姬","text":"子上，既然这样也就没什么好担心。"},{"type":"say","who":"王元姬","text":"就算皇上真的冲进大将军府来，还有我会挡在你的前面。"},{"type":"say","who":"司马昭","text":"元姬…"},{"type":"say","who":"王元姬","text":"太狡猾了，子上你可以不要用这种口气和我说话？壮烈成仁洛阳南阙"},{"type":"say","who":"曹髦","text":"中护军，你还不打算让开吗？"},{"type":"say","who":"贾充","text":"再往前进就是大将军的宅邸，陛下带著一群杀气腾腾的人往那里去，恕臣不能让您通过。"},{"type":"say","who":"曹髦","text":"你父亲贾梁道，谋国三世，不管在镇边或是中央都是声誉卓著的名臣，对大魏一片忠心，没想到会出了你这样的逆子。"},{"type":"say","who":"贾充","text":"（陛下，您这样的年轻人又懂什么呢？父亲可比我幸福多了，他一直都是侍奉武帝，可没有我这样仕二姓的问题。）"},{"type":"say","who":"贾充","text":"（你们这些上位者都只会指责臣下不忠，却不想想如果你的实力够强大，我们又何需对司马家卑躬屈膝。）"},{"type":"say","who":"许仪","text":"陛下，这里就交给俺，您可以继续往前进攻。"},{"type":"say","who":"曹髦","text":"不，没有这个必要了。"},{"type":"say","who":"许仪","text":"什么？！"},{"type":"say","who":"曹髦","text":"如果我让壮侯的儿子死在这种地方，恐怕武皇帝也会责怪我吧。"},{"type":"say","who":"许仪","text":"陛下，许家世世代代愿为曹家效死！"},{"type":"say","who":"曹髦","text":"朕真正的想法，恐怕就算是姑姑她也不懂。"},{"type":"say","who":"曹髦","text":"姑姑争长远的想法固然正确，但是只怕到时朝中已经没有人能支持曹氏了。"},{"type":"say","who":"曹髦","text":"如果可以见到姑姑的话，把这些话带给姑姑，就说曹髦用他的方法来复兴大魏。"},{"type":"say","who":"许仪","text":"陛下，您想要做什么？"},{"type":"say","who":"曹髦","text":"许仪，不管发生什么事情都不准出手。"},{"type":"say","who":"成济","text":"该怎么办，皇上居然不理会我们的劝阻。"},{"type":"say","who":"贾充","text":"（我和司马胄不一样，他有司马家血亲这金身可以免除责难，但我不行。）"},{"type":"say","who":"贾充","text":"（我和何晏有关系，李丰又曾经是我的岳父，司马家大有怀疑我的理由。然而我和司马家已经走太近，回不去了。）"},{"type":"say","who":"贾充","text":"（事到如今，只有表现出胜过一般人对司马家的忠诚，才是我的生存之道。）"},{"type":"say","who":"贾充","text":"司马公厚待你们，就是为了今天，这还有什么好问的？"},{"type":"say","who":"成济","text":"我明白了。"},{"type":"say","who":"成济","text":"（原来如此，这可是我发迹的大好机会呀。）"},{"type":"say","who":"曹髦","text":"哼…哈哈哈哈哈…"},{"type":"say","who":"成济","text":"有什么好笑的，你这死到临头的小鬼！"},{"type":"say","who":"曹髦","text":"没什么，你真的敢弑君？"},{"type":"say","who":"成济","text":"有什么好不敢的！你算什么东西，只不过是大将军的傀儡而已。"},{"type":"say","who":"成济","text":"傀儡想造反，下场就是死！"},{"type":"say","who":"曹髦","text":"说得真好，那么就来吧！"},{"type":"say","who":"许仪","text":"陛下！"},{"type":"say","who":"曹髦","text":"这样就没有遗憾了，朕让司马家背负弑君的罪名，只看其他人是否愿意觉醒了。"},{"type":"say","who":"曹髦","text":"姑姑一定会埋怨朕的傻劲，但是朕只有这样做，才能稍微阻挡司马昭的脚步。"},{"type":"say","who":"曹髦","text":"出现在我前面的是谁？朕本以为在这时代已经见不到这样充满英雄气概的人物。"},{"type":"say","who":"曹髦","text":"等一下…您是武皇帝吗？"},{"type":"say","who":"曹操","text":"还要躺在地上多久？是我的子孙，就想办法跟上来吧。"},{"type":"say","who":"曹髦","text":"武皇帝，请告诉我，我这样做对不对？"},{"type":"say","who":"曹操","text":"这个答案不该由我这个已死之人告诉你，而是应该由我的孙女来告诉你。"},{"type":"say","who":"曹髦","text":"姑姑吗？"},{"type":"say","who":"曹操","text":"走吧，我已经认可你是我曹家的优秀子孙，你有资格跟著我来征服这里。"},{"type":"say","who":"曹髦","text":"姑姑，剩下的事情就交给你了，请你务必要从司马家手中守护曹家。公元二六零年五月七日，曹髦率军反抗司马昭专政，被贾充教唆太子舍人成济杀害于南阙，得年二十岁。野心的崩坏洛阳大将军府"},{"type":"say","who":"司马昭","text":"公闾，你再说一遍，你到底做了什么事？"},{"type":"say","who":"贾充","text":"因为圣上执意要攻击大将军府，所以我命令成济下手杀了陛下。"},{"type":"say","who":"司马昭","text":"你杀了皇上？！这是何等滔天大罪，你知道吗？"},{"type":"say","who":"贾充","text":"当时情况危急，我真的没有别的选择了。"},{"type":"say","who":"司马昭","text":"这下可好，全天下都知道我司马昭弑君，我怎么向天下人交代？"},{"type":"say","who":"贾充","text":"真的很抱歉…"},{"type":"say","who":"王元姬","text":"子上，当初你让公闾出动军队保护你的时候，早就该料到会发生今天的事情。"},{"type":"say","who":"王元姬","text":"现在既然事情发生了，就该想办法善后，而不是留在原地发怒。"},{"type":"say","who":"司马昭","text":"对…你先下去吧…先让我把脑袋给冷静一下…太傅之痛洛阳南阙"},{"type":"say","who":"司马孚","text":"呜哇哇哇哇哇哇，为什么会这样啊…"},{"type":"say","who":"司马孚","text":"刺杀陛下，这全都是老夫的罪过…"},{"type":"say","who":"司马昭","text":"叔父大人，也请您节哀，发生这样不幸的事情，是我们大魏每个臣子的责任。"},{"type":"say","who":"司马孚","text":"子上，老夫已经很努力克制自己，不想当场给你难看。"},{"type":"say","who":"司马孚","text":"但是也希望你能够不要再出现在老夫眼前，不然老夫可能真的会忍不住了。"},{"type":"say","who":"司马昭","text":"叔父…"},{"type":"say","who":"司马孚","text":"当年你爹做那些事情的时候，老夫早该想到会有今天。"},{"type":"say","who":"司马孚","text":"过去抱著我们，跟我们在四叔府库里玩捉迷藏的二哥，早就已经变得面目全非。"},{"type":"say","who":"司马孚","text":"就因为老夫这个帮凶，帮二哥窃取了权力，最后让你们兄弟可以这样用来行凶。"},{"type":"say","who":"司马孚","text":"子元废了皇上已经够人神共愤，没想到子上你更厉害，还能直接杀了皇上。"},{"type":"say","who":"司马孚","text":"老夫老了，没用了，再怎么做也挡不住你要做什么。"},{"type":"say","who":"司马孚","text":"但是老夫也会马上上书要求严惩凶手，你自己看著办吧。"},{"type":"say","who":"司马昭","text":"（曹髦这一死，激化了朝野反司马家的力量，现在叔父也正式和我决裂，事情恐怕越演越烈。）"},{"type":"say","who":"司马昭","text":"（臭小子，把这样的烫手山芋丢给我，你的盘算就是这个？）消极的抗议洛阳宫殿"},{"type":"say","who":"司马昭","text":"圣上不幸崩逝，朝廷上下是一片混乱，身为相国的我必须责无旁贷地扛起守护国家的责任。"},{"type":"say","who":"高柔","text":"（谁不知道人是你杀的，但我现在又老又没有权力，还能做什么？）"},{"type":"say","who":"王祥","text":"（现在这又不是卧冰可以解决的事情，想说什么还不如哭吧。）"},{"type":"say","who":"王祥","text":"呜哇！！！！老臣无状啊…"},{"type":"say","who":"荀勖","text":"（这个王祥哭得像杀猪一样，这让我们这些亲近司马家的人有多尴尬。）"},{"type":"say","who":"王沈","text":"（也罢，反正我就是悲哀的懦夫，甚至连魏史都不敢写这些事情，请让我就这样庸庸碌碌过一生吧。）"},{"type":"say","who":"司马昭","text":"首先追究孙佑之罪，他看守阊阖门，居然阻挡安阳侯率军营救，似乎有参与叛逆的嫌疑，应该要予以族诛。"},{"type":"say","who":"荀勖","text":"这万万不可，孙佑拒绝安阳侯进入之罪，确实值得深究，但是事情总有合意与不合意的时候。"},{"type":"say","who":"荀勖","text":"为上者用刑，不可以因为喜怒而擅自减轻加重。"},{"type":"say","who":"荀勖","text":"就算要处罚，只该罚孙佑一人，如果杀了他的亲族，恐怕招来天下义士私下非议。"},{"type":"say","who":"司马昭","text":"你说的有道理，就只废他为庶人好了。"},{"type":"say","who":"司马昭","text":"嗯…等一下，太傅身体有微恙，缺席朝会是正常的，怎么尚书左仆射（陈泰）也不见了？"},{"type":"say","who":"司马昭","text":"尚书，这又是怎么回事？"},{"type":"say","who":"荀顗","text":"（惨了，我就知道会逼问我这件事情。）"},{"type":"say","who":"荀顗","text":"其实我也不是很清楚，不如让我去陈家那边看看吧。"},{"type":"say","who":"司马昭","text":"你是他的舅父，我想应该可以把他请来。"},{"type":"say","who":"司马昭","text":"要知道，颖川陈家和我河内司马家是世交，我可不想要破坏我们两家的交情呀。陈荀之比洛阳陈家"},{"type":"say","who":"荀顗","text":"我的好外甥呀，不要再做这种事情了，这对你或是陈家都没有好处。"},{"type":"say","who":"陈泰","text":"世人都认为我可以比得上舅父，现在看来你还远不如我。"},{"type":"say","who":"陈泰","text":"真是丢脸啊，想当初荀文若力抗武皇帝，就算服毒身死也从来没有低过一次头。"},{"type":"say","who":"陈泰","text":"然而舅父你呢？皇帝遇害，你装聋作哑就算了，现在还向司马家卑躬屈膝，当起他的传令兵来了。"},{"type":"say","who":"荀顗","text":"我们颖川荀家还能有什么选择？看见父亲的惨状，你认为我们还有这个勇气反抗？"},{"type":"say","who":"荀顗","text":"形势比人强，你要知道就连夏侯玄都会在一瞬间被屠灭三族，你认为你的名声比得过他？"},{"type":"say","who":"荀顗","text":"你大可以在见相国大人之后闭门不出都无所谓，但现在你一定得见他，给他个台阶下，不要让他没有面子。"},{"type":"say","who":"荀顗","text":"看看你外面跪著的子子孙孙，你就算不为自己想，也要为他们想呀。"},{"type":"say","who":"陈泰","text":"唉…平息之道洛阳大将军府"},{"type":"say","who":"司马昭","text":"呜呜…圣上就这样遇害…他还年轻呀…"},{"type":"say","who":"陈泰","text":"呜呜呜…"},{"type":"say","who":"司马昭","text":"玄伯，你说我该怎么办呢？"},{"type":"say","who":"陈泰","text":"只有诛杀贾充，才能平息天下的公愤。"},{"type":"say","who":"司马昭","text":"你可以再往下想想吗？"},{"type":"say","who":"陈泰","text":"我只能说到这里，不知道还有下面。"},{"type":"say","who":"司马昭","text":"………"},{"type":"say","who":"司马昭","text":"（如果说玄伯的想法代表天下人的想法的话，我势必得交出个人来解决这件事。）"},{"type":"say","who":"司马昭","text":"（但是贾充偏偏又是我的得力助手，要是杀了他，只怕其他人会从我身边离开。）"},{"type":"say","who":"陈泰","text":"（子上不可能杀贾充的，贾充帮了他这么大的忙，没赏赐他就已经很过分了。）"},{"type":"say","who":"陈泰","text":"（过去我对于司马家的专横都在装聋作哑，以为留在长安就可以置身事外。）"},{"type":"say","who":"陈泰","text":"（现在亲眼看到这样的事情发生，我若是再和司马家交好，就是让我陈家丢人。）"},{"type":"say","who":"陈泰","text":"（不过，我绝对不会眼睁睁看著你们司马家得逞的。）陈泰回府后，当场吐血数升后去世，这位镇边近十载，和姜维有来有往的名将，在这场弑君风暴中也倒了下来。他死后获追赠司空，谥穆侯。由儿子陈恂嗣侯。洛阳震动洛阳夏侯家地窖"},{"type":"say","who":"夏侯霸","text":"事情探听得如何？"},{"type":"say","who":"夏侯和","text":"二哥，圣上真的遇害了，行凶的虽然是成济，但是教唆他的却是贾充。"},{"type":"say","who":"夏侯霸","text":"这个贾充真是丢他父亲的脸，他父亲侍奉曹氏三代，一生刚直忠贞，哪知道会出现这样的逆子。"},{"type":"say","who":"夏侯和","text":"二哥，您该不会要冲出去报仇吧？"},{"type":"say","who":"夏侯霸","text":"我都可以在这里躲了快四年，你认为我还会像当年那样冲动？"},{"type":"say","who":"夏侯霸","text":"现在冲出去也于事无补，而且反而会害了七弟你。"},{"type":"say","who":"夏侯霸","text":"不过有件事情要麻烦你，尽快通知人在山阳的东乡公主，要她趁著司马家还没注意到她的时候脱身，不然就来不及了。"},{"type":"say","who":"夏侯和","text":"我一定会做到的。"},{"type":"say","who":"夏侯和","text":"二哥，您再忍耐一下，我相信您重见天日的时间应该不远了。洛阳太后寝宫叛逆的罪名"},{"type":"say","who":"郭太后","text":"大将军，这样你应该满意了吧？吾以不德，遭家不造，昔援立东海王子髦，以为明帝嗣，见其好书疏文章，冀可成济，而情性暴戾，日月滋甚。吾数呵责，遂更忿恚，造作丑逆不道之言以诬谤吾，遂隔绝两宫。其所言道，不可忍听，非天地所覆载。吾即密有令语大将军，不可以奉宗庙，恐颠覆社稷，死无面目以见先帝。大将军以其尚幼，谓当改心为善，殷勤执据。而此儿忿戾，所行益甚，举弩遥射吾宫，祝当令中吾项，箭亲堕吾前。吾语大将军，不可不废之，前后数十。此儿具闻，自知罪重，便图为弑逆，赂遗吾左右人，令因吾服药，密因酖毒，重相设计。事已觉露，直欲因际会举兵入西宫杀吾，出取大将军，呼侍中王沈、散骑常侍王业、尚书王经，出怀中黄素诏示之，言今日便当施行。吾之危殆，过于累卵。吾老寡，岂复多惜余命邪？但伤先帝遗意不遂，社稷颠覆为痛耳。赖宗庙之灵，沈、业即驰语大将军，得先严警，而此儿便将左右出云龙门，雷战鼓，躬自拔刃，与左右杂共入兵陈间，为前锋所害。此儿既行悖逆不道，而又自陷大祸，重令吾悼心不可言。昔汉昌邑王以罪废为庶人，此儿亦宜以民礼葬之，当令内外咸知此儿所行。又尚书王经，凶逆无状，其收经及家属皆诣廷尉。"},{"type":"say","who":"司马昭","text":"太后别这样说，您说的也都是事实，高贵乡公悖逆不道，遭到横死完全是咎由自取。"},{"type":"say","who":"司马昭","text":"他性情暴戾，诬谤太后，不听批评还反过来想杀太后。接著又想谋害大将军，所以遇害完全是天理昭彰。"},{"type":"say","who":"司马昭","text":"至于尚书王经参与叛逆，我会将他屠灭三族，以端正天下视听。"},{"type":"say","who":"郭太后","text":"够了，既然你已经达到目的，就请你出去吧。"},{"type":"say","who":"司马昭","text":"另外，国不可一日无君，常道乡公曹璜是燕王曹宇的儿子，品行端正又有名声，实在适合担任新君。"},{"type":"say","who":"郭太后","text":"随便你了。"},{"type":"say","who":"司马昭","text":"那么我就请新任中护军司马炎去迎接他继位了。"},{"type":"say","who":"郭太后","text":"（实在是太离谱了，曹璜根本就是明皇帝的从弟，怎么说也轮不到他继承，但是现在我又能说什么？）"},{"type":"say","who":"郭太后","text":"（明皇帝呀，我到底该怎么办，眼睁睁看著您的后代被杀，却完全不能反击，还得写这样污蔑他的文告。）"},{"type":"say","who":"郭太后","text":"（我不期望您能原谅我，只希望您能保佑曹氏一族能够复兴，给嚣张跋扈的司马家教训吧。）洛阳刑场死得其所"},{"type":"say","who":"王经","text":"娘，真的很对不起您，之前一直说想要让您过好日子，没想到却惹到这样的大祸。"},{"type":"say","who":"老妇","text":"人，谁能不死？只怕死得不是地方。为皇帝丧命，有什么好遗憾的呢？"},{"type":"say","who":"王经","text":"说得也是，我王经至少还可以抬头挺胸离开这世间呀。"},{"type":"say","who":"王沈","text":"（彦纬你走得真是坦荡，不像我只能像是虫子那样活著。我敬佩你的勇气，但是我真的做不到。）"},{"type":"say","who":"王沈","text":"（当初叔父给我取这样的名字，除了要我谦虚朴实外，也要我不被名利所惑，结果我完全没有做到…愧对自己的名字。）"},{"type":"say","who":"文官","text":"呜呜呜…王尚书，您的旧属向雄来给您送行了。尚书王经和其母被问斩，旧属向雄在街市痛哭，让在场所有人都跟著哀痛。而王沈则因通风报信有功，被封安平侯。山阳附近回归之途"},{"type":"say","who":"曹绫","text":"你跟我到这边就可以了，现在不是可以回去洛阳的时候，最好留在这边。"},{"type":"say","who":"桓楷","text":"听到皇上遇害的消息，我还不回去报仇，这样还是桓家的子孙？"},{"type":"say","who":"曹绫","text":"现在还不是时候，司马昭杀了王经，对于忠于大魏的人也不会忘记追捕。"},{"type":"say","who":"曹绫","text":"若是因为一时气愤而做出愚蠢的事情，那么就只会落得像皇上一样的下场。"},{"type":"say","who":"桓楷","text":"您这是说什么？陛下至少是奋战而死，您究竟又做了什么。"},{"type":"say","who":"曹绫","text":"…回去吧，日后若有复兴的机会，绝对用得著你，现在不是出来的时候。不久前　故山阳公邸最后的皇后"},{"type":"say","who":"曹节","text":"你为什么会来？你难道不怨恨我在十年前做的事情？"},{"type":"say","who":"曹绫","text":"您只是被司马懿利用而已，更何况若是我换成您的立场，应该也会做同样的决定。"},{"type":"say","who":"曹节","text":"可惜我的生命已经要走到尽头，没有办法去弥补我犯下的过错。"},{"type":"say","who":"曹绫","text":"曹家不会这么容易被打败的，现在的皇上年轻又聪明，只要再等个几年，复兴曹家绝对不是梦想。"},{"type":"say","who":"曹节","text":"你的韧性真的很强，换作是曹丕或是爹都不一定可以忍受你现在的处境。"},{"type":"say","who":"曹节","text":"或许你真的比较像是嫂子吧。"},{"type":"say","who":"曹绫","text":"姑姑…"},{"type":"say","who":"曹节","text":"虽然我很想祝福你成功，但是身为汉朝最后一任皇后，我却没有办法这样做。"},{"type":"say","who":"曹节","text":"想到献帝当时受到的痛苦，我就没有办法停止对曹丕的怨恨。"},{"type":"say","who":"曹绫","text":"我知道曹家过去对你的亏欠，祖父用您去监视献帝，父亲从你手中抢过玉玺，所以我希望能在您生命的最后一刻陪著您。"},{"type":"say","who":"曹节","text":"你有这个心就够了，我现在真正想见的人只有献帝而已，想到不久之后可以见他，其实我是很高兴的。"},{"type":"say","who":"桓楷","text":"山阳名士嵇康想求见故汉皇后，在下是他的信使。"},{"type":"say","who":"曹绫","text":"嵇中散胆子还真不小，他不知道旧汉臣属都受到监视？"},{"type":"say","who":"曹绫","text":"还是说，其实真正想要见我的是你这位信使呢？"},{"type":"say","who":"桓楷","text":"这…"},{"type":"say","who":"曹绫","text":"想说什么，就到外面说吧，我可不想让那些事情影响姑姑的病情。"},{"type":"say","who":"曹节","text":"快去吧，反正要见我这个亡国老妇随时都有机会。曹绫却不知道，这次的离去让她再也没有机会和曹节见面。一个月后曹节病故，被追諡为献穆曹皇后。她死前唯一的遗言就是：“皇上，希望来世能和你继续当夫妻。”因为她生前强硬的态度，虽然她是曹家人，仍然将她合葬于汉献帝刘协的禅陵，所用的车服礼仪皆遵从汉制。一个时辰前山阳附近忠臣聚集"},{"type":"say","who":"桓楷","text":"在下前大司农之子桓楷，知道公主您会前来山阳，特地来拜会。"},{"type":"say","who":"曹绫","text":"你很聪明，知道山阳这里虽然名为被监视的区域，实际上远比邺城甚至其他地方都还要松懈得多。"},{"type":"say","who":"桓楷","text":"对司马家来说，刘家根本就不足惧，反而曹家才是要监视的对象。"},{"type":"say","who":"曹绫","text":"你想说什么我大概都知道了。不过，这件事情要是曝光，可是连嵇康都会被牵连到，你想清楚了？"},{"type":"say","who":"桓楷","text":"我什么都不怕！"},{"type":"say","who":"曹绫","text":"不要这么心急，我们可以和司马家周旋的本钱是因为我们还有未来，只要皇帝还在，过几年之后，占上风的一定是我们。"},{"type":"say","who":"曹绫","text":"这位应该是夏侯义权将军吧，记得当年还在洛阳金殿上讨论过对抗诸葛亮的事情。"},{"type":"say","who":"夏侯和","text":"呼…呼…公主，现在不是叙旧的时候，洛阳发生大事情了…"},{"type":"say","who":"曹绫","text":"大事情？"},{"type":"say","who":"夏侯和","text":"圣上起兵反抗司马昭，在和贾充部队交战的时候遇害了。"},{"type":"say","who":"夏侯和","text":"现在洛阳进入戒严状态，若不是因为我是大将军府的幕僚，根本不能出来这里。"},{"type":"say","who":"曹绫","text":"你…是说…陛下他…遇害了…"},{"type":"say","who":"夏侯和","text":"这是千真万确的事情，我亲眼见到陛下的遗体倒在南阙那边，太傅司马孚还抱著陛下的遗体痛哭。"},{"type":"say","who":"曹绫","text":"我曹家的未来…希望…"},{"type":"say","who":"桓楷","text":"公主！"},{"type":"say","who":"夏侯和","text":"请振作点，我这次通知您这件事情，就是要您赶快离开洛阳离得越远越好，甚至逃到蜀国也没有关系。"},{"type":"say","who":"曹绫","text":"怎么可能？我逃到蜀地又有什么用，只会眼睁睁看著其他曹氏亲族受难而已。"},{"type":"say","who":"曹绫","text":"你先准备，我立刻和你返回洛阳。"},{"type":"say","who":"曹绫","text":"如果可以的话，我希望你能安排我和司马昭会面。王侯之礼洛阳宫殿"},{"type":"say","who":"司马昭","text":"高贵乡公曹髦由于刺杀皇太后未遂，而遭卫士格杀。"},{"type":"say","who":"司马昭","text":"太后因为曹髦的叛逆行为而感到悲痛万分，因此下诏将他贬为平民，以平民的身分下葬。"},{"type":"say","who":"司马孚","text":"大将军，你爱怎么做都随你便，老夫早就已经心死了。"},{"type":"say","who":"司马孚","text":"但是你需要对一个已死之人也这么残忍？"},{"type":"say","who":"司马孚","text":"你立了曹璜当皇帝，直接继承明皇帝老夫也没有意见，但是你不能把这六年的时间给抹消掉！"},{"type":"say","who":"司马昭","text":"叔父，这是太后的旨意，并不是我的想法。"},{"type":"say","who":"司马孚","text":"那么就跟太后说，我这老头子求求她，请她用王侯之礼埋葬他吧。"},{"type":"say","who":"司马昭","text":"叔父说的这些话，侄儿我早就有这样的想法，一切就请交给侄儿吧。"},{"type":"say","who":"荀勖","text":"（大将军实在是太奸了，这样变成贬圣上的是太后，为圣上求情的是他，他反倒成为有情有义的大好人。）不久后，大将军司马昭联合太傅司马孚、太尉高柔和司徒郑冲等上书太后：“伏见中令，故高贵乡公悖逆不道，自陷大祸，依汉昌邑王罪废故事，以民礼葬。臣等备位，不能匡救祸乱，式遏奸逆，奉令震悚，肝心悼栗。《春秋》之义，王者无外，而书｀襄王出居于郑＇，不能事母，故绝之于位也。今高贵乡公肆行不轨，几危社稷，自取倾覆，人神所绝，葬以民礼，诚当旧典。然臣等伏惟殿下仁慈过隆，虽存大义，犹垂哀矜，臣等之心实有不忍，以为可加恩以王礼葬之。”洛阳西北瀍涧交界最后一面"},{"type":"say","who":"男子","text":"这个就是前日被杀的天子吗？怎么那么凄凉？步兵你找死吗？给我安静点！"},{"type":"say","who":"女子","text":"真的好可怜，呜呜呜呜呜…"},{"type":"say","who":"夏侯和","text":"实在是太过分了，下车数乘，不设旌旐，这哪里是对待皇帝之礼？"},{"type":"say","who":"曹绫","text":"司马昭会这样做我也不意外，我想圣上一定让他饱受威胁吧。"},{"type":"say","who":"夏侯和","text":"公主，我早就和您说过，不要来看，我怕您会受不了。"},{"type":"say","who":"曹绫","text":"眼睁睁看著皇兄的两个儿子被杀被废却无能为力，我想哭都没有眼泪…"},{"type":"say","who":"曹绫","text":"带我去见司马昭吧，我还有些话要对他说。"},{"type":"say","who":"夏侯和","text":"这实在是太危险了，万一大将军他对您起了杀机…"},{"type":"say","who":"曹绫","text":"若是能这样死了，或许我还会轻松点，但恐怕就没脸见皇兄了。"},{"type":"say","who":"曹绫","text":"不用担心，司马昭不会杀我的。事件的终末洛阳大将军府"},{"type":"say","who":"司马昭","text":"义权，做得好，我正担心公主的安危。"},{"type":"say","who":"司马昭","text":"公主呀…发生这样的事情，实在是让我心痛不已…呜呜呜呜呜…"},{"type":"say","who":"曹绫","text":"大将军，您生命受到威胁居然还会关心要加害您的凶手，心胸实在是宽大无比。"},{"type":"say","who":"司马昭","text":"本来要问罪高贵乡公就不是我的主意，而是太后，这点你可以去看太后的诏令。"},{"type":"say","who":"曹绫","text":"高贵乡公？看来这六年也都没有存在过皇帝了是吗？"},{"type":"say","who":"司马昭","text":"这也是太后的主意，我什么都不知道。我唯一能做的，也就只有请太后以王侯之礼安葬皇上而已。"},{"type":"say","who":"曹绫","text":"刚才的王侯之礼我也见过了，确实是“隆重”非凡呀。"},{"type":"say","who":"曹绫","text":"大将军，我也不想再说些没有意义的话了…现在皇上已经驾崩，我也没有再留在这边的必要了。"},{"type":"say","who":"曹绫","text":"请求大将军把我送回邺城。"},{"type":"say","who":"司马昭","text":"（这个女人放弃了？回到邺城之后她是什么都不能做，到底她在想什么？）"},{"type":"say","who":"司马昭","text":"（不过这样也好，她不逼我杀她，我也没有必要对她动手。）"},{"type":"say","who":"司马昭","text":"好吧，既然公主这么坚持，那么过两天就派义权护送公主您上路吧。"},{"type":"say","who":"曹绫","text":"还有个请求，不知道大将军您能否答应？"},{"type":"say","who":"司马昭","text":"请说。"},{"type":"say","who":"曹绫","text":"壮侯的儿子许仪似乎因为参加这次的事件而被囚禁，不知道可以请大将军网开一面吗？"},{"type":"say","who":"司马昭","text":"有这样的事情？我马上派人传令放他出来。"},{"type":"say","who":"司马昭","text":"（比起王经，这个许仪根本就是小角色，就卖你个面子也无妨。）"},{"type":"say","who":"司马昭","text":"不过，既然他是壮侯的儿子，我想让他留在洛阳保护陛下的安全，可以吗？"},{"type":"say","who":"曹绫","text":"这种事情，大将军实在没有必要过问我的意见吧。"},{"type":"say","who":"司马昭","text":"请公主你保重了。"},{"type":"say","who":"曹绫","text":"嗯……那么我先告辞了。"},{"type":"say","who":"司马昭","text":"义权，你去送她，顺便把我命令带去廷尉那边，要他放了许仪。"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"司马昭","text":"（愁容满面，心灰意冷，双眼的泪痕都还没干，只是在这里硬撑着不哭出来而已。）"},{"type":"say","who":"司马昭","text":"（看来曹绫你真的完了…爹，我终于斗倒了这个女人，您看到了吗？）"},{"type":"say","who":"钟会","text":"大将军，难道就这样算了？斩草要除根，高贵乡公的背后一直都是这个女人负责策划的。"},{"type":"say","who":"钟会","text":"那个夏侯和，他也一直有些不寻常的举动，甚至传说他包庇一些曹爽、夏侯玄党羽的余孽。"},{"type":"say","who":"钟会","text":"另外那些名士表现出和大将军您不合作的态度也不可不注意，特别是山阳的嵇康…"},{"type":"say","who":"裴秀","text":"大将军，此举万万不可！现在外面对您的质疑还是闹得沸沸腾腾，若再开杀戮，对您的大业只有妨碍。"},{"type":"say","who":"荀勖","text":"（这个钟会真是浑帐，彷彿已经变成司马家的家奴一样，真是丢我堂外祖父钟太傅的脸。）"},{"type":"say","who":"荀勖","text":"（总有一天给你好看，顺便报上次偷我宝剑的仇。）"},{"type":"say","who":"裴秀","text":"（钟会这家伙怎么这么狠，现在居然要对名士也下手，他还是人吗？）"},{"type":"say","who":"司马昭","text":"秀彦说得对，如果我真照士季说的那样做，恐怕整个洛阳都要陷入一片血海。"},{"type":"say","who":"司马昭","text":"现在高贵乡公已死，其他人又能怎么样呢？曹绫她终究是女人，不管再怎么有才能，还是欠缺让人心服的能力。"},{"type":"say","who":"司马昭","text":"至于说嵇康，日前巨源也和我说要劝他出来作官，我就先观察一下吧。"},{"type":"say","who":"钟会","text":"您是说山巨源他愿意劝嵇康出来作官？"},{"type":"say","who":"司马昭","text":"虽说他和我有亲戚关系，但终归还是名士，他说话比我有份量多了。"},{"type":"say","who":"钟会","text":"原来如此…"},{"type":"say","who":"钟会","text":"（我看我也找个机会去拜访他一下，说不定可以抢在山涛之前说服嵇康，这样我在大将军面前就更吃香了。）"},{"type":"say","who":"司马昭","text":"倒是过了这么久的时间，我也该处理最后一件事情了。"},{"type":"say","who":"司马昭","text":"虽说我向太后推辞晋公的爵位，但光是这样恐怕还是难以平息天下人的怀疑。"},{"type":"say","who":"司马昭","text":"通知公闾，叫他过来见我。"},{"type":"say","who":"荀顗","text":"（莫非大将军真的要舍弃贾充了？）"},{"type":"say","who":"裴秀","text":"（我看贾充这次过关了，要是真要杀他，会要他过来见面？）"},{"type":"say","who":"裴秀","text":"（我大概知道是谁要倒楣了。）代罪羔羊洛阳宴会厅"},{"type":"say","who":"成倅","text":"老弟呀，这次你可是让我们成家大大露脸呀。"},{"type":"say","who":"成济","text":"可不是吗？瞧那中护军吓得像小鸡一样，若不是我机警，当机立断冲出去杀了那小子，恐怕现在大将军早就没命了。"},{"type":"say","who":"成倅","text":"既然你是大将军的救命恩人，一定会给你丰厚的赏赐呢。"},{"type":"say","who":"成济","text":"大将军大概在想要怎么赏赐我会比较好，烦恼了这么多天，想想也真过意不去。"},{"type":"say","who":"成济","text":"这不是贾大人吗？为什么跑来这个地方？是想和我们一起喝两杯？"},{"type":"say","who":"成倅","text":"我知道了，一定是大将军决定要怎么赏我们兄弟，才会派您来通知我们。"},{"type":"say","who":"贾充","text":"哼…两个蠢蛋…"},{"type":"say","who":"成济","text":"什么？！"},{"type":"say","who":"贾充","text":"太子舍人成济，杀害高贵乡公，大逆不道，现在交付廷尉处置。"},{"type":"say","who":"成济","text":"这是怎么回事？我不是救了大将军？"},{"type":"say","who":"贾充","text":"大将军岂可能被你等叛逆小人所救！"},{"type":"say","who":"成济","text":"大将军人很亲切和善的，这一定有什么误会。"},{"type":"say","who":"贾充","text":"误会？你自己看清楚大将军的上书。高贵乡公率将从驾人兵，拔刃鸣金鼓向臣所止；惧兵刃相接，即敕将士不得有所伤害，违令以军法从事。骑督成倅弟太子舍人济，横入兵陈伤公，遂至陨命；辄收济行军法。臣闻人臣之节，有死无二，事上之义，不敢逃难。前者变故卒至，祸同发机，诚欲委身守死，唯命所裁。然惟本谋乃欲上危皇太后，倾覆宗庙。臣忝当大任，义在安国，惧虽身死，罪责弥重。欲遵伊、周之权，以安社稷之难，即骆驿申敕，不得迫近辇舆，而济遽入陈间，以致大变。哀怛痛恨，五内摧裂，不知何地可以陨坠？科律大逆无道，父母妻子同产皆斩。济凶戾悖逆，干国乱纪，罪不容诛。辄敕侍御史收济家属，付廷尉，结正其罪。"},{"type":"say","who":"成济","text":"怎么会？！明明是你叫我动手的！"},{"type":"say","who":"贾充","text":"我从来没有下过这样的命令。"},{"type":"say","who":"成济","text":"司马昭，你这家伙真狠，把我兄弟俩用完了就丢。"},{"type":"say","who":"成倅","text":"如果不是我弟弟下手，谁又会帮他解决掉那个麻烦？到最后恩将仇报，真是个卑鄙小人！"},{"type":"say","who":"贾充","text":"带下去，我不想再看见这两个逆贼了。"},{"type":"say","who":"成济","text":"谁是逆贼？你才是逆贼，司马昭才是逆贼，这个事情全天下都知道。"},{"type":"say","who":"成倅","text":"就算是你杀了我们兄弟，也堵不了天下人的嘴，日后弑君者的姓名还是会写上你和司马昭的！"},{"type":"say","who":"贾充","text":"待会塞住他们的嘴，我可不希望他们的胡说八道影响到大将军的名誉。"},{"type":"say","who":"贾充","text":"（这次我是捡回一条命了，但是这十几天过得简直像是十几年一样，大将军真的没有动过要杀我的念头？）"},{"type":"say","who":"贾充","text":"（夹在中间当小人，贾充呀贾充，你什么时候变得这么可悲了？）公元二六零年五月二十六日，大将军司马昭上书指控成济兄弟大逆不道，诛杀其三族。又《魏氏春秋》记载，成济兄弟对于这样的罪状感到愤怒，于是脱掉上衣，爬到屋顶上大骂司马昭，之后被下面人乱箭射死。道别之言死牢"},{"type":"say","who":"许仪","text":"俺真是丢脸丢到极点，不但没有完成公主您的托付，还让陛下被司马昭那个奸贼害死。"},{"type":"say","who":"曹绫","text":"这不是你的责任。我忽视了皇上的个性，不断逼迫他忍耐才造成今天的结果。"},{"type":"say","who":"曹绫","text":"早知道皇上希望的结果是这样，或许我该选择和他一起慷慨赴死会比较好。"},{"type":"say","who":"许仪","text":"公主…像俺这样无用的武夫死了还没关系，但是像公主这样的人怎么可以轻易把死挂在嘴上。"},{"type":"say","who":"曹绫","text":"说得也是…看来你越来越有壮侯过去的风范了。"},{"type":"say","who":"曹绫","text":"听我说，现在我马上就要前往邺城，这次恐怕没办法这么容易回来洛阳。"},{"type":"say","who":"曹绫","text":"我取得司马昭释放你的命令，不久后你就可以获得自由。"},{"type":"say","who":"许仪","text":"公主，俺不能和您去邺城？"},{"type":"say","who":"曹绫","text":"你留在洛阳还有别的使命，代替我保护新皇帝，不要让他走上和皇上同样的路。"},{"type":"say","who":"曹绫","text":"接下来的日子，你得在洛阳继续忍受司马家的专横，但是请你一定要忍耐下去，拨云见日的一天终会到来。"},{"type":"say","who":"许仪","text":"公主…呜呜呜呜呜…"},{"type":"say","who":"曹绫","text":"像你这样的大块头，哭成这样实在是很难看。"},{"type":"say","who":"曹绫","text":"今日一别绝对不是永别，我们一定会有再相会的一天。"},{"type":"say","who":"许仪","text":"公主，请您一定要保重。"},{"type":"say","who":"曹绫","text":"我会的。东乡公主曹绫再次被送回邺城，和其他曹氏宗族一起被看管。六月一日，常道乡公曹璜则在中护军司马炎的护送下，从邺城抵达洛阳。同时间，郭太后下诏，因“璜”字太常见，难以避讳，命曹璜改名曹奂，年十五岁，大赦天下，改年号为“景元”。邺城东乡公主邸生存的希望"},{"type":"say","who":"曹绫","text":"曹家还剩下什么呢？当最后一个希望之火也被扑灭时，已经是无可奈何了。"},{"type":"say","who":"曹绫","text":"你是谁？你虽然看起来和我的侍女一样，但散发出的气息却怎么都不像侍女。"},{"type":"say","who":"女子","text":"别担心，我不会加害您，只是单纯来送一封信的。"},{"type":"say","who":"曹绫","text":"你是蜀人的密探对吧。"},{"type":"say","who":"女子","text":"是的，大将军有信要交给您，所以特命我潜入邺城。"},{"type":"say","who":"曹绫","text":"姜维有信要给我？好，我这就收下。"},{"type":"say","who":"女子","text":"那么我即刻回去覆命。"},{"type":"say","who":"曹绫","text":"我看看…"},{"type":"say","who":"曹绫","text":"现在放弃的话，大魏就结束了。希望迟早会到来，请再忍耐几时。"},{"type":"say","who":"曹绫","text":"…说得简单呀…"},{"type":"say","who":"曹绫","text":"………………送信的用意涪县姜维宅"},{"type":"say","who":"宁随","text":"我还是不能接受，伯约你居然要谍报部队去做这么无聊的事情。"},{"type":"say","who":"姜维","text":"抱歉了，我认为这是必要的。"},{"type":"say","who":"宁随","text":"告诉我吧，你送这信到底是为何？难道真的为了讨好那曹家公主？"},{"type":"say","who":"姜维","text":"司马昭弑君的事情你应该听过吧。"},{"type":"say","who":"宁随","text":"嗯，不过这和曹家公主有什么关系？"},{"type":"say","who":"姜维","text":"曹髦是她们曹家复兴的最后希望，却被司马昭用野蛮的手段铲除。"},{"type":"say","who":"姜维","text":"一个女子要扛起整个家族，面对司马家的威胁得挺身而出。"},{"type":"say","who":"姜维","text":"甚至到最后，看著自己亲人一个个被杀还不能在敌人面前掉泪，那需要多坚强的意志？"},{"type":"say","who":"姜维","text":"我怕她失去复兴的希望后，会一并失去求生的意志，所以想给她点希望。"},{"type":"say","who":"姜维","text":"她在我曾经放弃求生意志时拉了我一把，现在是换我回报的时候。"},{"type":"say","who":"宁随","text":"既然如此，我也不好多说什么了。"},{"type":"say","who":"宁随","text":"比起这个，你还是多关心一下成都的事吧，陈奉宗死后，你的处境可是一点也不会比那位公主乐观。"},{"type":"say","who":"姜维","text":"这我知道，但如果一直去思考那些事，只怕什么都做不成了。心腹大患建业皇宫"},{"type":"say","who":"张布","text":"陛下，不知道您有没有听过这样的传说？"},{"type":"say","who":"孙休","text":"传说？"},{"type":"say","who":"张布","text":"会稽那边有传说，会稽王孙亮不久后将要回去当皇帝。"},{"type":"say","who":"孙休","text":"笑话，根本就是没有根据的无稽之谈。"},{"type":"say","who":"孙休","text":"更何况朕从来就不在意这样的皇位，这个皇位本来就是皇弟的，只要他有这个意思，朕随时都可以把位子让给他。"},{"type":"say","who":"濮阳兴","text":"陛下，话可不能这样说呀。"},{"type":"say","who":"濮阳兴","text":"陛下您铲除奸臣孙綝，获得大吴臣民一致爱戴。相对来说，会稽王毫无作为，继位如何让人心服。"},{"type":"say","who":"濮阳兴","text":"更何况会稽王身边的宫女有密报，说他命巫师使用法术来诅咒陛下您。"},{"type":"say","who":"孙休","text":"没想到皇弟的个性居然扭曲成这样，如果不予以惩罚来矫正，恐怕会害了他。"},{"type":"say","who":"濮阳兴","text":"（陛下看来是已经动了杀机，我就说这世上哪会有人愿意把自己的皇位拱手让出呢？）"},{"type":"say","who":"孙休","text":"贬会稽王为“候官侯”，即刻遣送他前往自己的封地。"},{"type":"say","who":"孙休","text":"记住，要“好好”护送他前往封地，不能让他出半点“差错”。"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"张布","text":"公元二六零年，东吴会稽王孙亮于贬谪途中自杀。孙休大怒，处罚所有护送的人员。然而《三国志孙休传》引《吴录》却记载，有人认为孙亮是被孙休派人用鸩酒毒死。燕雀处堂建业皇宫"},{"type":"say","who":"孙休","text":"这次五官中郎将你出使蜀国真是辛苦了。"},{"type":"say","who":"孙休","text":"蜀国现在的情形如何？"},{"type":"say","who":"薛珝","text":"主上昏庸，不知道自己犯的错误。臣下苟且，只求不惹祸上身。"},{"type":"say","who":"薛珝","text":"到了那边，根本听不到正直的言论；经过原野，人民都面有菜色。"},{"type":"say","who":"薛珝","text":"臣曾听闻，燕雀停在高堂之上，以为这是最安全的地方，却不知烟囱已经冒火，栋梁已经焚烧。"},{"type":"say","who":"薛珝","text":"这些燕雀还兴高采烈，不知道大祸临头，大概就像现在蜀国这样。"},{"type":"say","who":"孙休","text":"没想到诸葛丞相不在时的蜀国会差这么多，实在是令人感慨。"},{"type":"say","who":"孙休","text":"幸好朕有两个得力助手帮忙，才不至于像蜀主那样，完全不知道自己犯的错误。"},{"type":"say","who":"张布","text":"臣惶恐…"},{"type":"say","who":"濮阳兴","text":"臣对陛下只有一片忠心。"},{"type":"say","who":"薛珝","text":"（我都快吐了，看这两个活宝当政，难道陛下不知道我们大吴也好不到哪去？）夺权之谋成都皇宫"},{"type":"say","who":"诸葛瞻","text":"为什么要我们来见你这个卑鄙小人？"},{"type":"say","who":"黄皓","text":"您肯来就表示您心中有所盘算不是吗？"},{"type":"say","who":"黄皓","text":"首先得恭喜三位升官。"},{"type":"say","who":"董厥","text":"哼，以思远的才干和家世，升到卫将军也不是什么意外的事情。"},{"type":"say","who":"黄皓","text":"您不也升到了辅国大将军，而且还和卫将军共平尚书事，实在是不简单呀。"},{"type":"say","who":"黄皓","text":"而侍中您也被圣上升为尚书令，以后大汉真的都要靠您们三个人了。"},{"type":"say","who":"樊建","text":"这些事情应该都与你无关吧。"},{"type":"say","who":"诸葛瞻","text":"有什么话就快说，我不认为你是单纯为了恭喜我们而把我们请到这来的。"},{"type":"say","who":"黄皓","text":"其实呢，我之前收到来自永安的信，那是右大将军写给我的。"},{"type":"say","who":"董厥","text":"文平？为什么他会寄信给你？"},{"type":"say","who":"黄皓","text":"右大将军实在是个忠臣，他对于姜维专横，连年用兵却没有建立功劳的事情感到忧心忡忡，所以才写信和我讨论这事。"},{"type":"say","who":"樊建","text":"像你这种小人也会关心大汉？别笑死人！"},{"type":"say","who":"黄皓","text":"话可不能这样说，我承蒙陛下的赏识才能有今天的地位。若是大汉有危险，陛下又岂能安稳坐在宝座呢？"},{"type":"say","who":"诸葛瞻","text":"（他说的话也不无道理，说不定这还是陛下的心思呢。）"},{"type":"say","who":"诸葛瞻","text":"我姑且相信你，那么你就说说打算怎么做吧。"},{"type":"say","who":"黄皓","text":"我想让右大将军来接替姜维担任大将军，这样就可以避免姜维继续让我大汉兵祸连年。"},{"type":"say","who":"董厥","text":"论才干，文平一点也不比姜维逊色。论经历，文平也担任过南中督和永安督，绝对可以胜任大将军一职。"},{"type":"say","who":"诸葛瞻","text":"我也同意，让文平担任大将军，绝对胜过那姜维百倍。且文平性格谨慎，不会胡乱用兵，可让我大汉休养生息。"},{"type":"say","who":"樊建","text":"我虽然赞成让文平担任大将军，但是我们为什么要和这样的小人合作？"},{"type":"say","who":"樊建","text":"我不想再听这个宦官废话了，请恕在下有事先行告退。"},{"type":"say","who":"黄皓","text":"尚书令不肯听完我的话，实在是很可惜。"},{"type":"say","who":"黄皓","text":"二位，请问您们真的了解陛下的心思？您们真的认为单凭上书就可以决定陛下意向？不要太小看陛下了。"},{"type":"say","who":"诸葛瞻","text":"你是说你有本事让陛下听从我们的建议，把文平提拔上来接替姜维？"},{"type":"say","who":"黄皓","text":"至少机会大些。如何？愿不愿意和我合作？对各位有利无害，而且又是为大汉尽忠。"},{"type":"say","who":"诸葛瞻","text":"（这样好吗？为了扳倒姜维而壮大黄皓，这样真的好吗？）"},{"type":"say","who":"黄皓","text":"各位别把我想成张让、赵忠之流的小人，陛下可不是灵帝呀！"},{"type":"say","who":"黄皓","text":"而且太监也有爱国的太监，不是吗？"},{"type":"say","who":"董厥","text":"我同意了，一切就拜托你了。"},{"type":"say","who":"诸葛瞻","text":"为了大汉，我宁愿和你合作也要阻止姜维的专横。"},{"type":"say","who":"诸葛瞻","text":"（百姓面有菜色，人民哀鸿遍野，这些都是我亲眼所见。不能阻止姜维胡乱出兵，就不能守护这块养了我三十年的土地。）"},{"type":"say","who":"诸葛瞻","text":"（父亲之灵在上，孩儿没有一点私心，一切只为了大汉的长治久安。）成都之行姜维军营帐"},{"type":"say","who":"姜维","text":"刚才接到胡济病逝的消息，如果是真的话，问题可就麻烦了。"},{"type":"say","who":"姜维","text":"现在正是汉中的防守策略在转换的时候，需要有一个强而有力的人去统筹。"},{"type":"say","who":"姜维","text":"朝廷如果不赶快派人来接替，只怕汉中防务会出现漏洞。"},{"type":"say","who":"姜维","text":"眼前我还必须要顾及西边的防务，不能分身管到汉中。"},{"type":"say","who":"来忠","text":"有件事情比胡济病故更严重，那就是成都那边在策画让阎宇顶替您的位子。"},{"type":"say","who":"来忠","text":"请大将军不要轻忽这样的讯息，能让爹在病情如此沉重的情况下还写这封信，事情绝对非同小可。"},{"type":"say","who":"柳隐","text":"成都的那些家伙在搞什么东西，他们真的以为阎宇那个蠢蛋可以取代老大？"},{"type":"say","who":"柳隐","text":"要是再这样搞下去，不如我们直接把军队带到成都给那些家伙好看算了！"},{"type":"say","who":"姜维","text":"休然，冷静点。"},{"type":"say","who":"柳隐","text":"啧…"},{"type":"say","who":"宁随","text":"阎文平以一个镇边将领来说，他还有不错的评价。但是如果要担任统率全国军队的大将军，他的实力就让人怀疑。"},{"type":"say","who":"句扶","text":"想也知道是黄皓那个小人，没想到他一个小小的太监居然能有这样的势力，几乎和陈祗生前不相上下。"},{"type":"say","who":"来忠","text":"但根据我爹信中表示，这次提案要罢免大将军的人是辅国大将军董厥和卫将军…"},{"type":"say","who":"蒋舒","text":"丞相公子…真令人意外…"},{"type":"say","who":"诸葛果","text":"主公，没能阻止弟弟的劣行，一切都是果的责任，请主公责罚…但是关于弟弟的的事情，也请主公交给我。"},{"type":"say","who":"杨兰","text":"（没想到丞相的儿子居然会参与倒姜维的行动，这也难为诸葛果了。）"},{"type":"say","who":"杨兰","text":"（更让我意外的是，这是诸葛果第一次面对姜维的敌人会没有表示要排除的意思，看来她真的很疼弟弟。）"},{"type":"say","who":"姜维","text":"我想丞相公子只是一时被迷惑，他绝对不是那种会和黄皓结交的人。"},{"type":"say","who":"姜维","text":"我要去成都一趟。"},{"type":"say","who":"姜维","text":"汉中督这个职位非常重要，朝廷绝对不能让这职位随便开缺，不然后果不堪设想。"},{"type":"say","who":"柳隐","text":"老大你位子都快不保了，居然还在管汉中的事情？"},{"type":"say","who":"宁随","text":"伯约，你千万不可以去！"},{"type":"say","who":"姜维","text":"为什么？边防的大事岂可儿戏？我想以陛下的圣明，应该可以理解的。"},{"type":"say","who":"宁随","text":"你还不懂吗？陈祗已经不在，没有人可以帮你在陛下面前说话了。"},{"type":"say","who":"姜维","text":"就算如此，我还是要把希望赌在陛下身上。"},{"type":"say","who":"宁随","text":"伯约呀，陛下从头到尾最信赖的人就只有黄皓。你若是贸然回到成都，黄皓他会怎么想？"},{"type":"say","who":"宁随","text":"到时候你和他起了冲突，请问陛下会袒护谁？"},{"type":"say","who":"姜维","text":"这些我也知道，陛下绝对会力挺黄皓。但是如果汉中防务放任废弛，所有作战计画将化为乌有。"},{"type":"say","who":"宁随","text":"你这一回去，只怕…你真的要大祸临头。姜维失坠成都皇宫"},{"type":"say","who":"刘禅","text":"中常侍，你有没有认为你做得太过火了？"},{"type":"say","who":"刘禅","text":"朕虽然因为你总是为朕著想而信赖你，但可没有准许你把手伸进政权和军权。"},{"type":"say","who":"黄皓","text":"奴才只是单纯认为这样对陛下比较好而已。"},{"type":"say","who":"刘禅","text":"姜维虽说多年征战都无功，但是换了阎宇真的会比较好？"},{"type":"say","who":"刘禅","text":"更何况阎宇和卫将军等人盘根错节的关系，让朕实在不放心。"},{"type":"say","who":"黄皓","text":"陛下，姜维虽然被孤立，看起来似乎可以为陛下所用，但是长年掌兵的他其实早就已经自成一系了。"},{"type":"say","who":"黄皓","text":"以他在军队的声望和实力，若是哪天反叛，把军队带回成都，后果可是不堪设想。"},{"type":"say","who":"黄皓","text":"看看少帝和献帝的下场，陛下可要三思。"},{"type":"say","who":"刘禅","text":"嗯…"},{"type":"say","who":"刘禅","text":"大将军，你来这边有什么事情吗？"},{"type":"say","who":"姜维","text":"关于汉中的人事…"},{"type":"say","who":"黄皓","text":"汉中的人事陛下自然会决定，这并非大将军您的权限，请您回去前线吧。"},{"type":"say","who":"姜维","text":"………"},{"type":"say","who":"黄皓","text":"呵呵呵…说真的，您担任大将军多年，却没有打过一场像样的胜仗，也没有为大汉增加一点疆土。"},{"type":"say","who":"黄皓","text":"真不知道您有什么脸来向陛下建议汉中的人事呢？"},{"type":"say","who":"姜维","text":"（我现在终于明白，为什么董休昭过去要对我说那些话了…）"},{"type":"say","who":"姜维","text":"陛下，臣说这样的话虽然僭越，但臣还是想说。"},{"type":"say","who":"姜维","text":"黄皓祸乱朝纲，造成正直之士有话却不敢说，这些事情臣都在前线有所耳闻。"},{"type":"say","who":"姜维","text":"望陛下查觉黄皓的恶行，将他诛杀以谢天下人，如此才能匡正政风。"},{"type":"say","who":"黄皓","text":"陛下救我！"},{"type":"say","who":"刘禅","text":"黄皓不过台阶前听候差遣的小小宦官。"},{"type":"say","who":"刘禅","text":"从前，董允只要一提起黄皓就咬牙切齿，朕深感遗憾，你何必把他放在心上？"},{"type":"say","who":"刘禅","text":"你就先回去歇息，到时候朕会让黄皓亲自登门向你道歉。"},{"type":"say","who":"姜维","text":"陛下…"},{"type":"say","who":"刘禅","text":"有什么话，等黄皓向你道歉过后再说吧。"},{"type":"say","who":"刘禅","text":"黄皓…你说的完全正确，姜维似乎已经开始有些胆大妄为了…"},{"type":"say","who":"刘禅","text":"你先去向他道歉，之后你要怎么做，朕都随你高兴。预言成都宫门"},{"type":"say","who":"谯周","text":"皇宫的大树无故折断，看来事情果然是这样…"},{"type":"say","who":"谯周","text":"（众而大，期之会，具而授，若何复？）"},{"type":"say","who":"谯周","text":"（看来早在当时我帮两位陛下算命就已经得到结论了。）"},{"type":"say","who":"谯周","text":"（刘备的“备”是“具有”的意思，而刘禅的“禅”是“授与”的意思。）"},{"type":"say","who":"谯周","text":"（这表示说刘氏已经具有了，应该授与他人。）"},{"type":"say","who":"谯周","text":"（这比晋穆侯、汉灵帝为两个儿子命名的个案，还要明显呀。）"},{"type":"say","who":"谯周","text":"（天下归曹魏是已经可以确定的事情，只是时间早晚而已。大汉所有的时日已经不多了呀。）出兵避祸成都宫殿门外"},{"type":"say","who":"郤正","text":"伯约，你刚才面圣说了些什么？"},{"type":"say","who":"姜维","text":"我请求陛下再次考虑人事案，但是没有获得陛下的首肯，只好先暂时回去。"},{"type":"say","who":"郤正","text":"只有这样？"},{"type":"say","who":"姜维","text":"我还请求陛下诛杀黄皓…"},{"type":"say","who":"郤正","text":"你终究还是做了…你惹祸上身了。"},{"type":"say","who":"郤正","text":"黄皓虽然有权势，但终究只是个奴才。你要知道是谁在后面给他撑腰的。"},{"type":"say","who":"郤正","text":"陛下对黄皓的信任超过你的想像，几乎黄皓说什么他都照单全收。"},{"type":"say","who":"郤正","text":"别以为黄皓不过是个小宦官，陛下如果认为你要动黄皓，就会认为你在挑战陛下的权威。"},{"type":"say","who":"郤正","text":"奉宗已经不在了，没有人能够在陛下前面帮你说话，你要知道这点呀。"},{"type":"say","who":"郤正","text":"只怕经过这次的事情，不但黄皓不会有事，反而伯约你还会遭到报复。"},{"type":"say","who":"郤正","text":"你被报复事小，但是大汉无人能领兵对抗曹贼事大，利害权衡，你自己想清楚。"},{"type":"say","who":"姜维","text":"果然如此呀，其实与其说陛下信任黄皓，倒不如说对我没有任何信任感。"},{"type":"say","who":"姜维","text":"奉宗一去世后，情况就变得太多了。"},{"type":"say","who":"郤正","text":"时代在变，人心在变，环境也在变。"},{"type":"say","who":"郤正","text":"除非你像丞相一样拥有凌驾于陛下的权力，要不然就得时时担心陛下的意向。"},{"type":"say","who":"姜维","text":"你知道我不会那样做的，丞相靠著自制立下的典范，不容许有人去破坏。"},{"type":"say","who":"姜维","text":"否则，我们和魏、吴这两国也没什么分别了。"},{"type":"say","who":"郤正","text":"一时之间，我也想不出什么好办法来挽回陛下的信任。"},{"type":"say","who":"姜维","text":"不，还有机会。"},{"type":"say","who":"姜维","text":"只要出兵获得像五年前洮西那样的胜利就行了。"},{"type":"say","who":"郤正","text":"事情哪那么容易呢？邓艾可还是守在那里等著伯约你呀。"},{"type":"say","who":"姜维","text":"如果就这样放弃的话，事情不就结束了？姜维知道让黄皓登门道歉一定会遭到报复，于是决定上书出兵，以进攻曹魏的方式，力图来挽回在朝中日渐失坠的地位。公元二六二年，蜀汉大将军姜维进攻洮阳（陇西郡），曹魏征西将军邓艾率军迎击，双方在侯和（陇西郡）展开对峙。最后的北伐姜维军营帐"},{"type":"say","who":"姜维","text":"这次我们能够重返熟悉的陇西并且得到羌人的帮助，实在是要感谢承宗这几年的辛劳。吕布被缚"},{"type":"say","who":"王嗣","text":"比起大将军为了重整战力的付出，我这点辛苦实在是不算什么。"},{"type":"say","who":"柳隐","text":"我们等这个机会已经很久了！"},{"type":"say","who":"赵统","text":"这次一定要好好修理邓艾！"},{"type":"say","who":"廖化","text":"不停发动战火，一定会把自己烧死，这就是姜维你的写照。"},{"type":"say","who":"廖化","text":"智谋赢不了别人，力量又不如敌人，发动这样永无止尽的攻击，怎么可能让自己能够生存呢？"},{"type":"say","who":"柳隐","text":"你这死老头！又在碎碎念些什么东西？"},{"type":"say","who":"廖化","text":"首先我是右车骑将军，本来就已经不属于常败军，这次只是因为协助作战才来的。"},{"type":"say","who":"廖化","text":"再来，似乎你这超过七十的老头也没什么资格说我吧。"},{"type":"say","who":"姜维","text":"现在应该要一起想办法如何击败挡在我们前面的邓艾，其他事情等以后再说吧。"},{"type":"say","who":"姜维","text":"（连元俭的态度都趋向反战，再加上成都的大臣们，北伐工作是越来越困难。）"},{"type":"say","who":"姜维","text":"对了，我们和邓艾相持多久了？"},{"type":"say","who":"袁綝","text":"大概有一个月左右了，贼营那边毫无动静，唯一就是这几天炊烟稍微多了一些。"},{"type":"say","who":"姜维","text":"炊烟…等等…从目前邓艾军队的炊烟可以推知敌人数量有多少？"},{"type":"say","who":"袁綝","text":"大概超过五万…等一下…莫非…"},{"type":"say","who":"姜维","text":"陇西军不可能有这样的数字，只是邓艾为什么要故意让我们认为有这么多人？"},{"type":"say","who":"诸葛果","text":"这只是一种想法，或许邓艾军故意制造出比平时还多的炊烟？"},{"type":"say","who":"姜维","text":"就是这个！邓艾他今天一定会分兵行动，所以让士兵一次煮两餐。"},{"type":"say","who":"廖化","text":"这样的想法有根据吗？光从炊烟推算敌人的行动，是不是太冒险了？"},{"type":"say","who":"姜维","text":"元俭，和邓艾交手过这么多次，你认为照著兵法可以制伏他？"},{"type":"say","who":"廖化","text":"确实是不行，那个家伙的用兵既精密却又难以捉摸。"},{"type":"say","who":"姜维","text":"所以我军如果利用他分兵的时候发动攻击，只要能够在分队到达前击破本队，这场战争获胜的机会就很高了。"},{"type":"say","who":"廖化","text":"……"},{"type":"say","who":"廖化","text":"（还是这么爱冒险，可是眼下我也提不出什么好计画。）"},{"type":"say","who":"姜维","text":"好，就照这样的作战策略，直接对邓艾本队发动攻击。"},{"type":"say","who":"姜维","text":"通知所有将士，连夜秘密转移阵地，不要让贼军发现。"},{"type":"say","who":"姜维","text":"我军阵地摆设依旧，火把也不要熄灭，另外布置草人使敌军误信营帐还有兵马。"},{"type":"say","who":"姜维","text":"而出击的部队，务必要用布包住马蹄，并且让所有士兵嘴巴含住一根草，禁止发出一点声音。"},{"type":"say","who":"姜维","text":"动作要快，否则邓艾的军队会…从后方夹击从四面包围"},{"type":"say","who":"姜维","text":"从后方夹击，到时我军会陷入两面包围。"},{"type":"say","who":"姜维","text":"会从左、右以及后方来包夹，到时我军会陷入四面包围的状态。產ち传"},{"type":"say","who":"姜维","text":"出击！这次一定要打倒邓艾！產ち传"},{"type":"say","who":"诸葛果","text":"主公，这个作战其实非常冒险，如不能在邓艾分队赶前时击破本队，面对两面夹击"},{"type":"say","who":"旁白","text":"▶ 是不可能获胜的。"},{"type":"say","who":"姜维","text":"我知道，但是要打倒邓艾就只能冒险。"},{"type":"say","who":"姜维","text":"（希望这样能让诸葛果打起精神来，不然真怕她弟弟的事情会一直搅扰她。）產ち传"},{"type":"say","who":"杨兰","text":"（本来想和诸葛果炫耀自己和姜维那阵子相处的时间，现在因为诸葛瞻的事情反而没办法这样做了。）"},{"type":"say","who":"杨兰","text":"（杨兰呀…你当好人要当到什么地步呢？再当下去恐怕就会变得和当年那个姓鲁的好人一样了。）產ち传"},{"type":"say","who":"来忠","text":"成都那边的气氛变得很诡异，请大将军一定要多小心。產ち传"},{"type":"say","who":"向充","text":"阎宇不算是弱者，但是比起大将军还是差很远。"},{"type":"say","who":"向充","text":"如果是他的话，恐怕邓艾根本不会浪费时间和他对峙。產ち传"},{"type":"say","who":"宁随","text":"（没想到陈祗会这么早死，让荆州年轻人提早接班实在不是好事。）"},{"type":"say","who":"宁随","text":"（现在情况恐怕就算打赢邓艾也不会改善，我得想出应对之道才行。）產ち传"},{"type":"say","who":"姜维","text":"很抱歉，这波谥号运动仍然没办法给陈将军一个谥号。"},{"type":"say","who":"袁綝","text":"别在意，义父他本身就不喜欢有什么特别的封号，他跟随先帝多年也从来没在乎过自己的职位。"},{"type":"say","who":"袁綝","text":"（比起义父的豁达，我还真是差得远。）產ち传"},{"type":"say","who":"廖化","text":"这次请让我当先锋！我虽然武艺上不是顶尖，但是以车骑将军的身分亲上前线，应该可以提升士兵的凝聚力。"},{"type":"say","who":"姜维","text":"可是你不是反对出兵吗？"},{"type":"say","who":"廖化","text":"反战归反战，我还不至于说会在大敌当前时扯自己人后腿。"},{"type":"say","who":"廖化","text":"只要在战场上，我就是大汉的军人，其他的事情以后再说。"},{"type":"say","who":"姜维","text":"元俭，多谢了。"},{"type":"say","who":"廖化","text":"（我要让你们看清楚，什么叫做真正为大汉尽忠。）產ち传"},{"type":"say","who":"柳隐","text":"陈祗之后又是黄皓，加上诸葛瞻那些人，成都的那些家伙到底是怎么回事？"},{"type":"say","who":"柳隐","text":"老大，如果你想过的话，早就可以取得政权，把那些碍事的人一脚踢开不是吗？"},{"type":"say","who":"姜维","text":"休然，说到这里就好。"},{"type":"say","who":"柳隐","text":"老大，请你一定要好好考虑清楚，再这样下去真的好吗？你的忠义换来什么？皇上"},{"type":"say","who":"旁白","text":"▶ 是怎么对你的？"},{"type":"scene","bg":"default","name":"產ち传"},{"type":"say","who":"句扶","text":"邓艾号称文武双全，但是这些年来他几乎都躲在后面，这算是什么武将？"},{"type":"say","who":"姜维","text":"真正的大将其实不需要站在前面，邓艾光是坐镇后方就会给人很大的压迫感。"},{"type":"say","who":"句扶","text":"哼！我一定要领教他的本领，看看他武艺高强的传闻是不是真的。產ち传"},{"type":"say","who":"王嗣","text":"伯约，虽说不能回复到洮西大捷时的声势，但我也已经尽力了。"},{"type":"say","who":"姜维","text":"承宗，你已经做得太多太好了，我若再对你要求就实在不配当人。"},{"type":"say","who":"王嗣","text":"这次我也会带领一些愿意帮助我们的羌人参战，希望能稍微弥补双方的战力差距。"},{"type":"say","who":"姜维","text":"承宗，明明你都这么辛苦了，又何必一定要参战？"},{"type":"say","who":"王嗣","text":"这是我的心愿，就请伯约成全我吧。"},{"type":"say","who":"姜维","text":"（承宗似乎有点操之过急了…难道他还是介意当时段谷的事情？）產ち传"},{"type":"say","who":"赵广","text":"顺平这样的谥号很适合爹，只是我不懂为什么陈祗那样的小人也可以有谥号？"},{"type":"say","who":"姜维","text":"陛下应该有他的考量吧…產ち传"},{"type":"say","who":"赵统","text":"感谢大将军为父亲请求谥号，还让父亲能和关、张等将军并列。"},{"type":"say","who":"姜维","text":"我认为这是赵云将军应得的，陛下也是很感念赵将军当年在当阳的救命之恩，所以很快就答应了。"},{"type":"say","who":"赵统","text":"如此，我兄弟更是要努力，才不至于让父亲的名声扫地。"},{"type":"battle","index":0}]},"battles":[{"index":0,"width":16,"height":10,"objective":"全灭敌军","grid":["ffffffffffffffff","ffffffffffffffff","ffppppppppppppff","fppppppppppppppf","fpwwwpppppwwwppf","fpwwpppppppwwppf","fpwwwpppppwwwppf","fppppppppppppppf","ffppppppppppppff","ffffffffffffffff"],"units":[{"def":{"name":"姜维","class":"commander","level":8,"skills":["fireball","heal","inspire"],"weapon":"sword","leader":true},"x":3,"y":4,"faction":"ally"},{"def":{"name":"赵云","class":"hero","level":9,"skills":["charge"],"weapon":"hualiu"},"x":4,"y":5,"faction":"ally"},{"def":{"name":"王平","class":"infantry","level":7,"skills":[],"weapon":"sword"},"x":3,"y":6,"faction":"ally"},{"def":{"name":"马岱","class":"dragoon","level":7,"skills":["charge"],"weapon":"halberd"},"x":5,"y":5,"faction":"ally"},{"def":{"name":"魏将","class":"officer","level":6,"skills":[],"weapon":"sword"},"x":11,"y":3,"faction":"enemy"},{"def":{"name":"魏将","class":"officer","level":6,"skills":[],"weapon":"sword"},"x":11,"y":7,"faction":"enemy"},{"def":{"name":"枪兵","class":"spearman","level":5,"skills":[],"weapon":"spear"},"x":10,"y":5,"faction":"enemy"},{"def":{"name":"弓兵","class":"archer","level":5,"skills":[],"weapon":"bow"},"x":13,"y":4,"faction":"enemy"}]}]});
})();
